'use strict';
let presentation=null;try{presentation=JSON.parse(sessionStorage.getItem('reu-presentation')||'null')}catch{}
let app=null,selected=presentation?.trainee||null,page='Overview',filter='All',busy=false,editorExam=null,trainerRecord=null,trainerEmail=null,encounterCount=0;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),arg=v=>esc(JSON.stringify(v));
const icon=(name='grid')=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',path:'M6 3v18 M6 5h12 M6 12h9 M6 19h12',book:'M3 4h7c2 0 2 1 2 2v15c0-2-2-2-4-2H3z M21 4h-7c-2 0-2 1-2 2v15c0-2 2-2 4-2h5z',shift:'M7 3v4 M17 3v4 M3 10h18 M5 5h14v16H5z',check:'M4 12l5 5L20 6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M15 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M6 2h8l4 4v16H6z M14 2v5h5 M9 12h6 M9 16h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`};
const badge=(s,t='')=>`<span class="badge ${t}">${esc(s)}</span>`,button=(text,fn,type='')=>`<button class="${type}" onclick="${fn}">${text}</button>`,card=(title,body,action='')=>`<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div><div class="cardbody">${body}</div></section>`,empty=text=>`<div class="empty">${icon('file')}${esc(text)}</div>`,progress=(v,total)=>`<div class="progress"><span style="width:${Math.min(100,total?v/total*100:0)}%"></span></div>`;
const me=()=>app?.account,person=()=>app?.people.find(p=>p.id===selected),rec=()=>app?.enrollments[selected],data=()=>rec()?.data,rdy=()=>rec()?.readiness,admin=()=>me()?.role==='admin',trainer=()=>['admin','trainer'].includes(me()?.role),mine=()=>me()?.role==='trainee',live=arr=>(arr||[]).filter(x=>!x.archived),date=v=>v?new Date(v).toLocaleDateString():'—',datetime=v=>v?new Date(v).toLocaleString():'—';
async function request(path,method='GET',value){const r=await fetch('/api/academy'+path,{method,credentials:'same-origin',headers:{...(sessionStorage.getItem('reu-active-role')?{'X-REU-Role':sessionStorage.getItem('reu-active-role')}:{}),...(value?{'Content-Type':'application/json'}:{}),...(presentation?{'X-REU-Presentation':'1','X-REU-Presentation-Role':presentation.role,'X-REU-Presentation-Trainee':presentation.trainee}: {})},...(value?{body:JSON.stringify(value)}:{})});let v;try{v=await r.json()}catch{throw Error('The server returned an unreadable response.')}if(!r.ok)throw Error(v.error||'Request failed.');return v}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>{$('#toast').style.display='none'},4500)}
async function load(){try{app=await request('/bootstrap')}catch(e){if(e.message==='This role is not assigned to your account.'){sessionStorage.removeItem('reu-active-role');app=await request('/bootstrap')}else throw e}if(!app.people.some(p=>p.id===selected))selected=app.people[0]?.id||null;render();if(!sessionLogged){sessionLogged=true;browserEvent('session-open',{page})}checkReminders(true)}
function go(next){page=next;filter='All';browserEvent('page-view',{page:next});render();checkReminders(false);window.scrollTo({top:0,behavior:'smooth'})}
function choose(id){selected=id;if(presentation){presentation.trainee=id;sessionStorage.setItem('reu-presentation',JSON.stringify(presentation))}render()}
function selectPerson(){return app.people.length?`<select class="enrollment-select" aria-label="Selected trainee" onchange="choose(this.value)">${app.people.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${esc(p.license)}</option>`).join('')}</select>`:''}
function heading(eyebrow,title,description,action=''){if(title.startsWith('Welcome,'))return `<section class="welcome-panel"><div class="welcome-copy"><span class="welcome-tag">READING EMERGENCY UNIT · TRAINING TOGETHER</span><h1>${esc(title)}.</h1><p>A clear path forward, with your REU team beside you.</p><div class="welcome-context">${esc(description)}</div>${action?`<div class="welcome-selection">${action}</div>`:''}</div><div class="welcome-emblem"><img src="./reu-patch.jpg" alt="Reading Emergency Unit"><span>Learn. Practice. Serve.</span></div></section>`;return `<div class="titlebar"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p class="muted small" style="margin:0">${esc(description)}</p></div>${action}</div>`}

function stat(label,value,detail=''){return `<div class="stat"><label>${esc(label)}</label><strong>${esc(value)}</strong><small>${esc(detail)}</small></div>`}
function row(title,sub,actions='',tag=''){return `<div class="row"><div><h3>${esc(title)}</h3><p>${esc(sub)}</p></div><div class="actions">${tag}${actions}</div></div>`}
function legacy_navItems(){let items=[['Overview','grid'],['Training hub','path'],['Training path','path'],['Lessons','book'],['Shift workspace','shift'],['Daily PQS','check'],['Shift calendar','shift'],['Skills and PQS','check'],['Scenarios','shield'],['Final assessment','file']];if(!mine())items.push(['FTO academy','book']);if(admin())items.push(['Review desk','check'],['Team and access','people'],['Activity log','file']);items.push(['Program handbook','book'],['Resources','file']);if(admin())items.push(['Program settings','settings']);return items}
function render(){if(!app)return;const nav=navItems();if(!nav.some(([n])=>n===page))page='Overview';const views={'Overview':overview,'Onboarding':onboardingView,'Concerns':concernsView,'Training hub':trainingHub,'Training path':pathView,'Lessons':lessonsView,'Shift workspace':shiftsView,'Daily PQS':dailyPqsView,'Skills and PQS':skillsView,'Scenarios':scenariosView,'Final assessment':examView,'FTO academy':ftoView,'Review desk':reviewView,'Team and access':teamView,'Program handbook':handbookView,'Resources':resourcesView,'Program settings':settingsView,'Activity log':activityView,'Shift calendar':calendarView};let body;if(!selected&&!['Overview','Review desk','Team and access','Program settings','FTO academy','Program handbook','Resources','Activity log'].includes(page))body=heading('REU academy','No trainee assigned','An administrator must link or assign your trainee profile.')+empty('Use Team and access to create or assign a trainee.');else body=views[page]();$('#app').innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><a href="#" class="brand" onclick="go('Overview');return false"><img src="./reu-patch.jpg" alt="REU patch"><div><strong>READING</strong><small>EMERGENCY UNIT</small></div></a><div class="nav-label">YOUR TRAINING COMMUNITY</div><nav class="nav" aria-label="Main navigation">${sidebarNavigation()}</nav><div class="side-links"><a href="https://secure13.aladtec.com/reu/" target="_blank" rel="noopener noreferrer">Aladtec scheduler ↗</a><a href="https://app.targetsolutions.com/auth/index.cfm?action=login.showlogin&customerid=32461&customerpath=readingemergency" target="_blank" rel="noopener noreferrer">TargetSolutions ↗</a></div><div class="side-foot"><span class="dot"></span>Shared training records<br>${esc(app.catalog.version)}</div></aside><div class="main"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation" onclick="$('#sidebar').classList.toggle('open')">☰</button><div class="breadcrumb">REU Academy <span style="margin:0 8px">/</span> ${esc(pageLabel(page))}</div><a class="signout-link" href="#" onclick="signOutReu();return false">Sign out</a>${themeSelector()}<div class="identity"><div><strong>${esc(me().name)}</strong><div class="role">${me().role==='trainer'?'FIELD TRAINING OFFICER':esc(me().role.toUpperCase())}</div></div><span class="avatar">${esc(me().name.split(' ').map(w=>w[0]).join('').slice(0,2))}</span></div></header><main class="content">${roleSwitchBar()}<div id="shiftReminderBanner" aria-live="polite"></div>${!app.settings.adoption?`<div class="notice amber"><strong>Program draft · ${esc(app.catalog.version)}</strong> — Training content and workflows are available for review. Formal release stays locked until the program and clinical references are adopted.</div>`:''}${sectionNavigation()}${body}<footer class="footer"><span>READING EMERGENCY UNIT</span><span>FIELD TRAINING AND EVALUATION</span></footer></main></div></div>`;document.title='REU Academy · '+pageLabel(page)}
function overall(){const r=rdy();return {complete:r.lessons.complete+r.skills.filter(s=>s.complete).length+r.scenarios.filter(s=>s.complete).length+r.hours.filter(h=>h.approved).length,total:r.lessons.total+r.skills.length+r.scenarios.length+5}}
function legacy_overview(){const p=person(),d=data(),r=rdy(),o=overall(),phase=app.catalog.phases[d.currentPhase-1],shifts=live(d.shifts).slice().sort((a,b)=>b.start.localeCompare(a.start));const pending=shifts.filter(s=>!shiftCompleteUI(s));
 let next={title:'Start with your training day',description:'Review the goals and lessons for your current phase.',label:'Open my training',action:"go('Training hub')"};
 if(mine()){
  const daily=shifts.find(s=>(s.pqsRequired||s.dailyPqs)&&!['Submitted','Signed'].includes(s.dailyPqs?.status));
  const response=shifts.find(s=>s.status!=='Draft'&&(!s.traineeResponse||s.traineeResponse.status==='Returned'));
  const feedback=shifts.find(s=>s.status!=='Draft'&&(!s.trainerFeedback||s.trainerFeedback.status==='Returned'));
  if(daily)next={title:'Complete your daily PQS',description:date(daily.start)+' · Tell your FTO what you were shown and practiced.',label:'Open this day’s checklist',action:`openDailyPqs(${arg(daily.id)})`};
  else if(response)next={title:'Complete your shift response',description:date(response.start)+' · Review your coaching and record your response.',label:'Open shift response',action:`responseForm(${arg(response.id)},'response')`};
  else if(feedback)next={title:'Give feedback on your FTO',description:date(feedback.start)+' · Complete your confidential trainer feedback.',label:'Open feedback form',action:`responseForm(${arg(feedback.id)},'feedback')`};
 }else if(admin()){
  const count=app.people.reduce((total,p)=>total+live(app.enrollments[p.id].data.shifts).reduce((n,s)=>n+[s,s.traineeResponse,s.trainerFeedback].filter(v=>v?.status==='Submitted').length,0),0);
  next=count?{title:count+' submitted forms need review',description:'Approve completed paperwork or return it with correction instructions.',label:'Review submitted forms',action:"go('Review desk')"}:{title:'Manage your training team',description:'Select a trainee to review their progress, paperwork and release requirements.',label:'Open trainee roster',action:"go('Team and access')"};
 }else{
  const unsigned=shifts.find(s=>s.dailyPqs?.status==='Submitted'&&s.evaluator===me().email),draft=shifts.find(s=>s.status==='Draft'&&s.evaluator===me().email);
  next=unsigned?{title:'Sign the daily PQS',description:date(unsigned.start)+' · Your trainee has submitted the checklist for your evaluation.',label:'Review and sign checklist',action:`openDailyPqs(${arg(unsigned.id)})`}:draft?{title:'Finish your shift evaluation',description:date(draft.start)+' · Continue your saved evaluation before submitting it.',label:'Continue shift evaluation',action:`openShift(${arg(draft.id)})`}:{title:'Record a completed training shift',description:'Start the FTO evaluation, then complete the daily PQS with your trainee.',label:'Create shift record',action:'openShift()'};
 }
 if(d.release)next={title:'Training record finalized',description:'Review the final authorization'+(admin()?' and download the training record.':'.'),label:'View completion',action:"go('Final assessment')"};
 return heading('Your REU workspace','Welcome, '+me().name.split(' ')[0],'Choose your next task below.',selectPerson())+`<section class="next-action"><div><div class="eyebrow">START HERE</div><h2>${esc(next.title)}</h2><p>${esc(next.description)}</p>${button(esc(next.label),next.action,'primary')}</div><div class="current-phase"><small>${esc(p.name)} · ${esc(p.license)}</small><strong>Phase ${d.currentPhase}</strong><span>${esc(phase.title)}</span></div></section><div class="home-actions">${homeTile('Shift paperwork','Daily checklist, FTO evaluation and trainee forms.','Open shift paperwork',"go('Shift workspace')",'shift')}${homeTile('Training','Current-day goals, lessons and practical qualifications.','Open training',"go('Training hub')",'book')}${homeTile(admin()?'Progress and downloads':'My progress',admin()?'Readiness, release decisions and compact/full report downloads.':'Accepted hours, required credentials and final assessment readiness.',admin()?'Open progress and downloads':'View my progress',"go('Final assessment')",'file')}</div><div class="stats">${stat('Accepted hours',r.hours.reduce((n,h)=>n+h.actual,0)+' / '+r.hours.reduce((n,h)=>n+h.required,0))}${stat('Lessons completed',r.lessons.complete+' / '+r.lessons.total)}${stat('Qualified skills',r.skills.filter(x=>x.complete).length+' / '+r.skills.length)}${stat('Shift records awaiting completion',pending.length)}</div>`;
}

function shiftCompleteUI(s){return s.status==='Reviewed'&&s.traineeResponse?.status==='Reviewed'&&s.trainerFeedback?.status==='Reviewed'&&(!(s.pqsRequired||s.dailyPqs)||['Signed','Reviewed'].includes(s.dailyPqs?.status))}
function legacy_pathView(){const d=data(),r=rdy();return heading('REU learning pathway','Your Reading Emergency Unit training pathway','REU PQS day labels describe 24-hour training-day teaching focuses, not automatic advancement dates. Your assigned hours, license pathway, competencies and documented reviews govern progression.',selectPerson())+app.catalog.phases.map(ph=>{const h=r.hours.find(x=>x.id===ph.id),ml=app.catalog.modules.filter(m=>m.phase===ph.id&&m.levels.includes(person().license)),sk=app.catalog.skills.filter(s=>s.phase===ph.id&&s.levels.includes(person().license));return card(`<span class="badge">PHASE ${ph.id}</span> ${esc(ph.title)}`,`<p class="small muted">${esc(ph.goal)}</p>${ph.reuFocus?`<h3>${esc(ph.reuLabel)}</h3>${button('Open daily PQS check-off sheets',"go('Daily PQS')")}<ul>${ph.reuFocus.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions">${app.catalog.modules.filter(m=>m.phase===ph.id&&m.levels.includes(person().license)).map(m=>button(m.title,`openLesson(${arg(m.id)})`)).join('')}</div>`:''}<div class="stats" style="margin-bottom:10px">${stat('Accepted hours',h.actual+' / '+h.required)}${stat('Lessons',ml.filter(m=>d.lessons[m.id]?.passed).length+' / '+ml.length)}${stat('Competencies',sk.filter(s=>r.skills.find(x=>x.id===s.id)?.complete).length+' / '+sk.length)}${stat('Phase decision',h.approved?'Approved':ph.id===d.currentPhase?'Current phase':'Not yet reviewed')}</div>${ph.id===d.currentPhase?`<div class="notice">${rec().phaseBlockers.length?rec().phaseBlockers.map(esc).join('<br>'):'Phase requirements are ready for an administrator review.'}</div><div class="actions">${trainer()?button('Recommend phase decision',`decision('phase-request','Phase recommendation','Summarize performance, remaining gaps, and your recommendation.')`):''}${admin()?button('Record phase review','phaseReviewForm()','primary'):''}</div>`:''}`)}).join('')}
function lessonsView(){const list=app.catalog.modules.filter(m=>m.levels.includes(person().license)&&(filter==='All'||String(m.phase)===filter));return heading('Trainee learning','The learning pathway','Read the lesson, practice with your FTO, and complete the knowledge check.',selectPerson())+`<div class="pill-row">${['All','1','2','3','4','5'].map(v=>button(v==='All'?'All phases':'Phase '+v,`filter=${arg(v)};render()`,filter===v?'active':'')).join('')}</div><div class="cards">${list.map(m=>`<section class="card lesson-card"><div class="eyebrow">PHASE ${m.phase} · ${m.minutes} MINUTE LEARNING ACTIVITY</div><h2>${esc(m.title)}</h2><p>${esc(m.objectives.join(' '))}</p><div class="wide-label">${badge(data().lessons[m.id]?.passed?'Knowledge check passed':'Not completed',data().lessons[m.id]?.passed?'green':'')}<button onclick="openLesson(${arg(m.id)})">${mine()?'Open lesson':'Review lesson'} →</button></div></section>`).join('')}</div>`}
function showModal(title,body,eyebrow='REU ACADEMY'){browserEvent('form-open',{title});const dialog=$('#modal');$('#modalContent').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h2>${esc(title)}</h2></div><button type="button" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function closeModal(){$('#modal').close()}
function field(name,label,type='text',value='',required=true){return `<label class="field">${esc(label)}${required?' *':''}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function area(name,label,value='',required=true){return `<label class="field">${esc(label)}${required?' *':''}<textarea name="${esc(name)}" ${required?'required':''}>${esc(value)}</textarea></label>`}
function select(name,label,options,value='',required=true){return `<label class="field">${esc(label)}${required?' *':''}<select name="${esc(name)}" ${required?'required':''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`}
const check=(name,label,checked=false)=>`<label class="check"><input type="checkbox" name="${esc(name)}" ${checked?'checked':''}>${esc(label)}</label>`,actions=(label='Save')=>`<p class="form-error" id="formError" role="alert"></p><div class="form-actions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">${esc(label)}</button></div>`;
function formValues(form){return Object.fromEntries(new FormData(form))}
function bindForm(fn){$('#activeForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const btn=e.target.querySelector('button.primary');btn.disabled=true;try{await fn(formValues(e.target),e.target)}catch(err){$('#formError').textContent=err.message}finally{busy=false;if(btn.isConnected)btn.disabled=false}}}
async function mutate(action,values={},id=selected){const e=app.enrollments[id];const result=await request('/trainees/'+encodeURIComponent(id)+'/action','POST',{...values,action,etag:e.etag});await load();return result}
function questionFields(qs,answers={}){return qs.map((q,i)=>`<fieldset class="quiz"><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((o,n)=>`<label><input type="radio" name="${esc(q.id)}" value="${n}" ${answers[q.id]===n?'checked':''} required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}
function openLesson(id){const m=app.catalog.modules.find(m=>m.id===id);if(!m)return;const complete=data()?.lessons[id];showModal(m.title,`<div class="reading"><div class="actions">${badge('Phase '+m.phase)}${complete?badge('Completed '+date(complete.at),'green'):badge('Not completed')}</div><h3>Learning objectives</h3><ul>${m.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${m.sections.map(s=>`<h3>${esc(s.heading)}</h3><p>${esc(s.text)}</p>`).join('')}<div class="practice"><h3>Practice with your FTO</h3><p>${esc(m.practice)}</p></div><h3>REU practical evidence</h3><p>${esc(m.reuEvidence||'Record observed performance separately in Skills and PQS.')}</p><p class="small muted">Source: REU Training Expectations, updated PQS, and FTO completion checklist. Current approved MCA protocols and device instructions govern clinical practice.</p><h3>Knowledge check</h3>${mine()?`<form id="activeForm">${questionFields(m.questions)}${area('reflection','What will you apply on your next shift?')}${actions('Submit knowledge check')}</form>`:`${m.questions.map(q=>`<p><strong>${esc(q.prompt)}</strong></p><ul>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>`).join('')}<p class="notice">Only the trainee can submit their own knowledge check. Practical qualification is recorded separately by the evaluator.</p>`}</div>`,'TRAINEE LESSON · '+app.catalog.version);if(mine())bindForm(async(v)=>{const answers=Object.fromEntries(m.questions.map(q=>[q.id,Number(v[q.id])])),r=await mutate('lesson',{moduleId:id,answers,reflection:v.reflection});showModal(r.result.passed?'Knowledge check passed':'Review and try again',`<p>You scored <strong>${r.result.score}%</strong>.</p>${r.feedback.map(f=>`<h3>${esc(f.prompt)}</h3><p><strong>${esc(f.correct)}</strong><br>${esc(f.explanation)}</p>`).join('')}<button class="primary" onclick="closeModal()">Return to learning</button>`);})}
function legacy_shiftsView(){const d=data(),shifts=live(d.shifts).slice().sort((a,b)=>b.start.localeCompare(a.start));return heading('Field training','Shift paperwork','Choose a shift below to complete its checklist, evaluation or trainee forms.',selectPerson())+`<div class="actions" style="margin-bottom:20px">${trainer()&&!d.release?button('＋ New training shift','openShift()','primary'):''}${button('View remediation plans','openPlans()')}</div>`+(!shifts.length?card('Training shifts',empty('No training shifts recorded. Your FTO starts the first shift evaluation.')):shifts.map(s=>card(`${esc(date(s.start))} · Phase ${s.phase} · ${s.hours} eligible hours`,`<div class="step-meta"><span>${esc(datetime(s.start))} – ${esc(datetime(s.end))}</span><span>${esc(s.evaluatorName||s.evaluator)}</span></div><p class="small" style="margin-top:14px"><strong>Objectives</strong><br>${esc(s.objectives)}</p><p class="small"><strong>Coaching and next steps</strong><br>${esc(s.sharedFeedback)}</p><div class="actions">${badge('FTO evaluation: '+s.status,s.status==='Reviewed'?'green':'amber')}${badge('Trainee response: '+(s.traineeResponse?.status||'Required'),s.traineeResponse?.status==='Reviewed'?'green':'amber')}${badge('FTO feedback: '+(s.trainerFeedback?.status||'Required'),s.trainerFeedback?.status==='Reviewed'?'green':'amber')}</div><div class="actions" style="margin-top:18px">${button('Daily PQS: '+(s.dailyPqs?.status||'Not started'),`openDailyPqs(${arg(s.id)})`)}${button('View shift',`viewShift(${arg(s.id)})`)}${trainer()&&s.status==='Draft'&&(admin()||s.evaluator===me().email)?button('Edit draft',`openShift(${arg(s.id)})`)+button('Attest and submit',`submitShift(${arg(s.id)})`,'primary'):''}${mine()&&s.status!=='Draft'&&(!s.traineeResponse||s.traineeResponse.status==='Returned')?button('Submit shift response',`responseForm(${arg(s.id)},'response')`,'primary'):''}${mine()&&s.status!=='Draft'&&(!s.trainerFeedback||s.trainerFeedback.status==='Returned')?button('Give FTO feedback',`responseForm(${arg(s.id)},'feedback')`):''}${admin()?reviewButtons(s):''}</div>`,s.criticalFailure?badge('Safety concern','red'):shiftCompleteUI(s)?badge('Paperwork complete','green'):'')).join(''))}
const ratingLabels={safety:'Scene and crew safety',assessment:'Patient assessment',care:'Care and reassessment',protocols:'Protocol application',documentation:'Documentation',communication:'Communication',operations:'Equipment and operations',professionalism:'Professionalism',leadership:'Leadership'};
function localInput(v){const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function legacy_openShift(id,schedule=null){const s=id?data().shifts.find(s=>s.id===id):null,finish=schedule?new Date(schedule.end):new Date(),start=schedule?new Date(schedule.start):new Date(finish.getTime()-8*3600000);encounterCount=0;showModal(s?'Edit draft shift':'New training shift',`<form id="activeForm"><div class="formgrid">${field('start','Actual shift start','datetime-local',localInput(s?.start||start))}${field('end','Actual shift end','datetime-local',localInput(s?.end||finish))}${field('excludedMinutes','Nontraining minutes','number',s?.excludedMinutes||0)}${field('phase','Current approved phase','number',data().currentPhase)}</div><p class="form-note">Dates use your browser’s local time. Eligible hours are calculated from actual time minus nontraining time. Overlapping shifts are rejected.</p>${area('objectives','Measurable shift objectives',s?.objectives||'')}<h3 class="sectiontitle">Performance ratings</h3><p class="form-note">1 = unsafe / substantial intervention; 2 = coaching required; 3 = safe without routine prompting; 4 = exceeds standard. Not observed is unscored.</p><div class="formgrid">${Object.entries(ratingLabels).map(([k,l])=>select(k,l,[['NA','Not observed'],[1,'1 — Unsatisfactory'],[2,'2 — Developing'],[3,'3 — Competent'],[4,'4 — Exceeds standard']],s?.ratings?.[k]??'NA')).join('')}</div>${check('criticalFailure','A critical safety failure occurred',s?.criticalFailure)}${check('coaching','Routine coaching was required',s?.coaching)}${area('sharedFeedback','Objective coaching and next steps — visible to trainee',s?.sharedFeedback||'')}${area('privateNotes','Confidential evaluator notes — administrator and author only',s?.privateNotes||'',false)}<h3 class="sectiontitle">Encounter and PCR evidence</h3><p class="form-note">Use unique nonidentifying references. Do not enter patient names, birth dates, addresses, or copied PCR text. An actual lead encounter counts once; a simulation does not count as a live encounter.</p><div id="encounters"></div><button type="button" onclick="addEncounter()">＋ Add encounter</button>${actions('Save shift draft')}</form>`,'FTO SHIFT EVALUATION');for(const e of s?.encounters||[])addEncounter(e);if(!s?.encounters.length)addEncounter();bindForm(async(v,form)=>{const ratings=Object.fromEntries(Object.keys(ratingLabels).map(k=>[k,v[k]==='NA'?null:Number(v[k])])),encounters=[];for(let i=0;i<encounterCount;i++)if(v['ref'+i]?.trim())encounters.push({reference:v['ref'+i],role:v['role'+i],category:v['category'+i],actual:v['actual'+i]==='on',independent:v['independent'+i]==='on',pcrReviewed:v['pcr'+i]==='on',substantiveCorrection:v['correction'+i]==='on'});await mutate('shift',{shift:{id:s?.id,scheduleId:s?.scheduleId||schedule?.id||null,start:new Date(v.start).toISOString(),end:new Date(v.end).toISOString(),phase:Number(v.phase),excludedMinutes:Number(v.excludedMinutes),objectives:v.objectives,ratings,encounters,sharedFeedback:v.sharedFeedback,privateNotes:v.privateNotes,criticalFailure:v.criticalFailure==='on',coaching:v.coaching==='on'}});closeModal();toast('Shift draft saved')})}
function addEncounter(e={}){const i=encounterCount++;$('#encounters').insertAdjacentHTML('beforeend',`<section class="encounter"><div class="formgrid">${field('ref'+i,'Encounter reference','text',e.reference||'',false)}${select('role'+i,'Trainee role',['Lead','Assist','Observe'],e.role||'Lead')}${select('category'+i,'Category',['Medical','Trauma','Pediatric','Respiratory','Cardiac','Transfer','Other'],e.category||'Medical')}</div>${check('actual'+i,'Actual patient encounter',e.actual??true)}${check('independent'+i,'Lead without routine coaching',e.independent)}${check('pcr'+i,'Trainee-authored PCR reviewed',e.pcrReviewed)}${check('correction'+i,'Substantive PCR correction required',e.substantiveCorrection)}</section>`)}
function submitShift(id){showModal('Submit FTO shift evaluation',`<form id="activeForm"><p>Submission records your signed-in evaluator identity and locks the evaluation for review. The trainee can then submit their response and private feedback.</p>${check('attest','I attest that this record accurately reflects my observed shift and evaluation.')}${actions('Attest and submit')}</form>`);bindForm(async v=>{await mutate('submit-shift',{shiftId:id,attest:v.attest==='on'});closeModal();toast('Evaluation submitted')})}
function legacy_responseForm(id,kind){const s=data().shifts.find(s=>s.id===id),old=kind==='response'?s.traineeResponse:data().ownFeedback?.[id];showModal(kind==='response'?'Trainee shift response':'Private feedback on your FTO',`<form id="activeForm">${kind==='response'?area('reflection','What did you learn and perform?',old?.reflection||'')+area('response','Your response to the shift feedback',old?.response||'')+area('nextPlan','Your plan for the next shift',old?.nextPlan||''):`<p class="notice">Your feedback is visible to you and the administrator. It is not shown to the FTO.</p><div class="formgrid">${['instruction','clarity','professionalism','safety'].map(k=>select(k,k[0].toUpperCase()+k.slice(1),[1,2,3,4],old?.[k]||3)).join('')}</div>${area('comments','Specific feedback and suggestions',old?.comments||'')}`}<p class="form-note">Submission records your authenticated acknowledgment. It does not require agreement with every evaluator rating.</p>${actions('Submit form')}</form>`);bindForm(async v=>{await mutate(kind,{shiftId:id,form:kind==='response'?v:{...v,instruction:Number(v.instruction),clarity:Number(v.clarity),professionalism:Number(v.professionalism),safety:Number(v.safety)}});closeModal();toast('Trainee form submitted')})}
function reviewButtons(s){return ['shift','response','feedback'].map(type=>{const x=type==='shift'?s:type==='response'?s.traineeResponse:s.trainerFeedback;return x?.status==='Submitted'?button('Review '+(type==='shift'?'evaluation':type),`reviewForm(${arg(s.id)},${arg(type)})`):''}).join('')}
function reviewForm(id,type){const s=data().shifts.find(s=>s.id===id),record=type==='shift'?s:type==='response'?s.traineeResponse:s.trainerFeedback;showModal('Review '+(type==='shift'?'FTO evaluation':type==='response'?'trainee response':'FTO feedback'),`<div class="reading">${type==='shift'?`<p><strong>${esc(s.objectives)}</strong></p><p>${esc(s.sharedFeedback)}</p><h3>Confidential evaluator notes</h3><p>${esc(s.privateNotes||'None.')}</p><table>${Object.entries(s.ratings||{}).map(([k,v])=>`<tr><th>${esc(ratingLabels[k])}</th><td>${v??'Not observed'}</td></tr>`).join('')}</table><p>${s.hours} eligible hours · ${s.encounters.length} encounters</p>`:Object.entries(record).filter(([k])=>!['review','status','at','by'].includes(k)).map(([k,v])=>`<h3>${esc(labelFor(k))}</h3><p>${esc(v)}</p>`).join('')}</div><form id="activeForm">${select('decision','Review decision',['Approve','Return'])}${area('notes','Review notes — retained in the record')}${actions('Record review')}</form>`);bindForm(async v=>{await mutate('review-'+type,{...v,shiftId:id});closeModal();toast('Review recorded')})}
function legacy_viewShift(id){const s=data().shifts.find(s=>s.id===id);showModal('Shift record — '+date(s.start),`<div class="reading"><p><strong>Phase ${s.phase} · ${s.hours} eligible hours</strong><br>${esc(datetime(s.start))} – ${esc(datetime(s.end))}<br>Evaluator: ${esc(s.evaluatorName||s.evaluator)}</p><h3>Objectives</h3><p>${esc(s.objectives)}</p><h3>Shared coaching</h3><p>${esc(s.sharedFeedback)}</p>${s.ratings?`<h3>FTO ratings</h3><table>${Object.entries(s.ratings).map(([k,v])=>`<tr><th>${esc(ratingLabels[k])}</th><td>${v??'Not observed'}</td></tr>`).join('')}</table>`:''}${s.privateNotes?`<h3>Confidential evaluator notes</h3><p>${esc(s.privateNotes)}</p>`:''}<h3>Encounter evidence</h3>${s.encounters.map(e=>`<p><strong>${esc(e.reference)}</strong> · ${esc(e.role)} · ${e.actual?'Actual':'Simulated'}<br>${e.independent?'Independent lead':'Coached / other role'} · ${e.pcrReviewed?'PCR reviewed':'No PCR review'}${e.substantiveCorrection?' · Substantive correction required':''}</p>`).join('')||'<p>None.</p>'}<h3>Trainee response</h3>${s.traineeResponse?`<p>${esc(s.traineeResponse.reflection)}</p><p>${esc(s.traineeResponse.response)}</p><p>${esc(s.traineeResponse.nextPlan)}</p>`:'<p>Not submitted.</p>'}${admin()&&s.trainerFeedback?`<h3>Private trainer feedback</h3><p>${esc(s.trainerFeedback.comments)}</p>`:''}${s.attestation?`<p class="form-note">Evaluator attestation: ${esc(s.attestation.name)} · ${esc(datetime(s.attestation.at))}</p>`:''}${admin()&&!data().release?button('Archive this shift',`decision('archive','Archive shift','Explain why this record should be archived. Its history will be retained.',{collection:'shifts',recordId:${arg(id)}})`,'danger'):''}</div>`)}
function skillsView(){const p=person(),d=data();const list=app.catalog.skills.filter(s=>s.levels.includes(p.license)&&(filter==='All'||String(s.phase)===filter));return heading('Personnel qualification standard','Skills and PQS','Learn the standard, practice with your FTO, and preserve every assessed attempt.',selectPerson())+`<div class="pill-row">${['All','1','3','4','5'].map(v=>button(v==='All'?'All competencies':'Phase '+v,`filter=${arg(v)};render()`,filter===v?'active':'')).join('')}</div>`+card('Applicable competencies',`<div>${list.map(s=>{const st=rdy().skills.find(x=>x.id===s.id);return `<details class="details"><summary><span>${esc(s.id)} · ${esc(s.title)}</span>${badge(st.complete?'Qualified':st.count+' / '+st.required,st.complete?'green':'')}</summary><div class="reading"><p><strong>Passing standard</strong><br>${esc(s.standard)}</p><h3>Teach and practice</h3><p>${esc(s.teaching)}</p><ol>${s.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="notice amber"><strong>Critical failure</strong><br>${esc(s.critical)}</div><p class="small"><strong>Reassessment:</strong> ${esc(s.remediation)}</p><p class="form-note">${esc(s.reviewStatus)} · Reference candidate: ${esc(s.source)}. Current governing instructions control clinical practice.</p><div class="actions">${trainer()&&!d.release?button('Record skill assessment',`skillForm(${arg(s.id)})`,'primary'):''}${button('View assessment history',`skillHistory(${arg(s.id)})`)}</div></div></details>`}).join('')}</div>`)}
function skillForm(id){const s=app.catalog.skills.find(s=>s.id===id),shifts=live(data().shifts).filter(sh=>sh.status!=='Draft'&&sh.phase>=s.phase).sort((a,b)=>b.start.localeCompare(a.start));if(!shifts.length)return toast('Submit a training shift in this competency’s phase or later before attaching an assessment.');showModal(s.id+' · '+s.title,`<form id="activeForm">${select('shiftId','Training shift',shifts.map(s=>[s.id,date(s.start)+' · Phase '+s.phase]))}${field('reference','Nonidentifying encounter or skill-sheet reference')}${select('mode','Assessment conditions',['Observed','Coached','Independent'],'Independent')}<p class="form-note">A qualification needs ${s.repetitions} successful demonstration${s.repetitions===1?'':'s'}, including one without prompting. Observation alone does not count.</p>${s.steps.map((step,i)=>`<div class="assessment-step"><span>${i+1}. ${esc(step)}</span>${select('step'+i,'Step '+(i+1),['Not observed','Pass','Needs practice'],'Not observed')}</div>`).join('')}<div class="notice amber">${esc(s.critical)}</div>${check('criticalFailure','A critical failure occurred — this attempt cannot pass.')}${area('notes','Objective performance, coaching, and debrief')}${actions('Attest and record assessment')}</form>`,'AUTHENTICATED EVALUATOR ATTESTATION');bindForm(async v=>{await mutate('skill',{skillId:id,shiftId:v.shiftId,reference:v.reference,mode:v.mode,steps:s.steps.map((_,i)=>v['step'+i]),criticalFailure:v.criticalFailure==='on',notes:v.notes});closeModal();toast('Skill assessment recorded')})}
function skillHistory(id){const s=app.catalog.skills.find(s=>s.id===id),entries=live(data().skills).filter(e=>e.skillId===id);showModal(s.title+' — assessment history',entries.length?entries.slice().reverse().map(e=>`<div class="cardbody"><h3>${esc(date(e.at))} · ${e.passed?'Successful demonstration':'Practice / reassessment required'}</h3><p>${esc(e.mode)} · ${esc(e.reference)}<br>${esc(e.evaluatorName||e.evaluator)}</p><p>${esc(e.notes)}</p>${e.criticalFailure?badge('Critical failure','red'):''}</div>`).join(''):empty('No attempts recorded.'))}
function scenariosView(){return heading('Applied learning','Scenario library','Instructor cases, changing conditions, performance rubrics, and recorded assessments.',selectPerson())+`<div class="cards">${app.catalog.scenarios.map(s=>{const done=rdy().scenarios.find(x=>x.id===s.id)?.complete;return `<section class="card lesson-card"><div class="eyebrow">${s.duration} MINUTE EXERCISE</div><h2>${esc(s.title)}</h2><p>${esc(s.setup)}</p><div class="wide-label">${badge(done?'Passed':'Required',done?'green':'')}<button onclick="openScenario(${arg(s.id)})">Open exercise →</button></div></section>`}).join('')}</div>`}
function openScenario(id){const s=app.catalog.scenarios.find(s=>s.id===id);showModal(s.title,`<div class="reading"><h3>Setup</h3><p>${esc(s.setup)}</p><h3>Instructor inject</h3><p>${esc(s.inject)}</p><h3>Expected performance</h3><p>${esc(s.expected)}</p><div class="notice amber">${esc(s.critical)}</div></div>${trainer()&&!data().release?`<form id="activeForm">${field('date','Exercise date','date',new Date().toLocaleDateString('en-CA'))}<div class="formgrid">${s.rubric.map((r,i)=>select('rating'+i,r,[1,2,3,4],3)).join('')}</div>${check('criticalFailure','Critical failure occurred')}${area('notes','Scenario evidence, performance, and debrief')}${actions('Record scenario assessment')}</form>`:'<p class="form-note">Your evaluator records the practical assessment. Each domain must meet the independent standard.</p>'}`);if(trainer()&&!data().release)bindForm(async v=>{await mutate('scenario',{scenarioId:id,date:v.date,ratings:s.rubric.map((_,i)=>Number(v['rating'+i])),criticalFailure:v.criticalFailure==='on',notes:v.notes});closeModal();toast('Scenario assessment recorded')})}
function legacy_examView(){const d=data(),r=rdy(),passed=r.passedExam,authorized=d.examAuthorization?.version===app.settings.examVersion&&d.examAuthorization.remaining>0;return heading('Training progress','Progress, completion and downloads','Training completion, knowledge assessment, and the final approval are separate recorded decisions.',selectPerson())+(admin()?`<div class="actions report-shortcuts">${button('Download compact summary','downloadCompactReport()','primary')}${button('Download full training record','downloadReport()')}</div>`:'')+`<div class="stats">${stat('Actual lead encounters',r.actualEncounters+' / 20','Final five without routine coaching')}${stat('PCR reviews',r.pcrReviews+' / 10','Final five without substantive correction')}${stat('Scenario categories',r.scenarios.filter(x=>x.complete).length+' / '+r.scenarios.length)}${stat('Qualified evaluators',r.evaluators+' / 2','Evidence from at least two evaluators')}</div><div class="grid"><div>${card('Training readiness',r.eligible?'<p class="notice">Every required training gate is complete.</p>':`<ul class="status-list">${r.blockers.map(x=>`<li><span class="status-icon pending">○</span><div>${esc(x)}</div></li>`).join('')}</ul>`)}${card('Required credentials and external courses',r.credentials.map(c=>{const pending=live(d.credentials).filter(v=>v.title===c.title);return `<div class="row"><div><h3>${esc(c.title)}</h3><p>${pending.map(x=>(x.verified?'Verified':'Awaiting verification')+(x.expires?' · Expires '+x.expires:'')).join(' / ')||'Evidence not supplied'}</p></div><div class="actions">${badge(c.complete?'Verified':'Required',c.complete?'green':'amber')}${!d.release&&(mine()||admin())?button('Add evidence',`credentialForm(${arg(c.title)})`):''}</div></div>`}).join(''))}${card('Final knowledge assessment',`<p class="small">Passing score: <strong>${app.settings.passPercent}%</strong>. Every safety-critical item must be correct. The current exam must be reviewed and published by the administrator.</p>${!app.settings.examPublished?'<p class="notice amber">The final exam is a draft and is not available for live attempts.</p>':''}<div class="actions">${mine()?`<button class="primary" ${!passed&&r.eligible&&app.settings.examPublished&&(authorized||d.activeExam)?'':'disabled'} onclick="takeExam()">${d.activeExam?'Resume final assessment':'Start final assessment'}</button><span class="small muted">${passed?'Current exam passed':d.activeExam?'Attempt in progress':authorized?'Attempt authorized':'Administrator authorization required'}</span>`:''}${admin()?button('Review and edit exam bank','manageExam()')+button('Authorize final attempt',`decision('authorize-exam','Authorize final assessment','Confirm your readiness review and authorize one attempt. This control cannot bypass the training gates.')`,'primary'):''}</div>${d.examAttempts.length?`<div class="tablewrap"><table><tr><th>Submitted</th><th>Version</th><th>Score</th><th>Outcome</th></tr>${d.examAttempts.map(a=>`<tr><td>${esc(datetime(a.at))}</td><td>${a.version}</td><td>${a.score}%</td><td>${esc(!a.valid?'Readiness changed':a.passed?'Passed':'Retake review required')}</td></tr>`).join('')}</table></div>`:''}`)}</div><div>${card('Final authorization',d.release?`<p>${badge('Finalized','green')}</p><h3>Effective ${esc(d.release.effectiveDate)}</h3><p class="small">Recorded by ${esc(d.release.name)}<br>${esc(datetime(d.release.at))}</p><p class="small">${esc(d.release.notes)}</p><p class="small"><strong>Restrictions</strong><br>${esc(d.release.restrictions||'None recorded.')}</p>${admin()?`<div class="actions">${button('Download compact summary','downloadCompactReport()','primary')+button('Download full training record','downloadReport()')}${button('Reopen training',`decision('reopen','Reopen training','Explain the reason. The prior release is retained and a new readiness review and exam are required.')`)}</div>`:''}`:`<p class="small muted">Finalization requires completed training, a passed current exam, and the required clinical and operational approval references.</p>${admin()?button('Record final release','releaseForm()','primary'):'<p class="small">An administrator records the final decision.</p>'}`)}${card('Credentials and evidence files',d.attachments.length?d.attachments.map(f=>`<p class="small"><a href="/evidence/${encodeURIComponent(selected)}/${encodeURIComponent(f.id)}" onclick="downloadEvidence(${arg(f.id)},${arg(f.name)});return false">${esc(f.name)} ↓</a><br><span class="muted">${Math.ceil(f.size/1024)} KB · ${esc(date(f.at))}</span></p>`).join(''):empty('Upload a credential or course certificate when adding evidence.'))}${card('Training record',`<p class="small muted">Submitted records retain authenticated authorship and review history. Finalized reports are locked until an administrator reopens training.</p>${admin()?`<div class="actions">${button('Download compact summary','downloadCompactReport()','primary')}${button('Download full training record','downloadReport()')}</div>`:''}`)}</div></div>`}
function credentialForm(title){showModal(title+' — evidence',`<form id="activeForm">${field('reference','Credential number or external completion reference')}${field('expires','Expiration date, if applicable','date','',false)}<label class="field">Evidence file — optional PDF PNG or JPEG<input type="file" name="evidence" accept="application/pdf,image/png,image/jpeg"></label><p class="form-note">Maximum 10 MB. Upload only the credential or course evidence needed for training. No patient records.</p>${actions('Submit credential evidence')}</form>`);bindForm(async(v,form)=>{let fileId='';const file=form.elements.evidence.files[0];if(file){const r=await fetch('/api/academy/trainees/'+encodeURIComponent(selected)+'/upload',{method:'POST',credentials:'same-origin',headers:{...presentationHeaders(),'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name),'X-Record-Version':rec().etag||'new'},body:file});const value=await r.json();if(!r.ok)throw Error(value.error);fileId=value.fileId;await load()}await mutate('credential',{title,reference:v.reference,expires:v.expires,fileId});closeModal();toast('Credential evidence submitted for verification')})}
function decision(action,title,description,extra={}){showModal(title,`<p class="small muted">${esc(description)}</p><form id="activeForm">${area('notes','Decision notes and evidence reference')}${actions('Record decision')}</form>`);bindForm(async v=>{await mutate(action,{...extra,notes:v.notes});closeModal();toast('Decision recorded')})}
function legacy_phaseReviewForm(){showModal('Phase '+data().currentPhase+' review',`<p class="form-note">Advancement is checked against accepted hours, lesson checks, applicable skills, scenario requirements, completed paperwork, and open remediation.</p><form id="activeForm">${select('decision','Decision',['Advance','Continue','Extend'])}${area('notes','Evidence, decision, next objectives, and restrictions')}${actions('Record phase review')}</form>`);bindForm(async v=>{await mutate('phase-review',v);closeModal();toast('Phase review recorded')})}
function openPlans(){const plans=live(data().remediation);showModal('Remediation and reassessment',`${plans.length?plans.map(p=>`<section class="cardbody"><h3>${esc(p.title)} ${badge(p.closed?'Closed':'Open',p.closed?'green':'red')}</h3><p><strong>Observed deficiency</strong><br>${esc(p.deficiency)}</p><p><strong>Expected standard</strong><br>${esc(p.standard)}</p><p><strong>Instruction and practice</strong><br>${esc(p.instruction)}</p><p class="small">Review date: ${esc(p.due||'To be assigned')}<br>Evaluator: ${esc(p.assignedEvaluator||'Training Officer')}<br>Restrictions: ${esc(p.restrictions||'See current supervision plan.')}</p>${!p.closed&&trainer()?button('Complete or edit plan',`planForm(${arg(p.id)})`):''}${p.closed?`<p class="small">Closed by ${esc(p.closure.by)} · ${esc(p.closure.evidence)}</p>`:admin()?button('Document successful reassessment',`closePlan(${arg(p.id)})`):''}</section>`).join(''):empty('No remediation plans recorded.')}${trainer()&&!data().release?button('＋ Create remediation plan','planForm()','primary'):''}`)}
function planForm(id){const plan=id?data().remediation.find(p=>p.id===id):null;showModal(plan?'Complete remediation plan':'Create remediation plan',`<form id="activeForm">${field('title','Plan title','text',plan?.title||'')}${area('deficiency','Specific observed deficiency',plan?.deficiency||'')}${area('standard','Required performance standard',plan?.standard||'')}${area('instruction','Instruction and practice assignments',plan?.instruction||'')}${area('restrictions','Temporary restrictions',plan?.restrictions||'',false)}<div class="formgrid">${field('due','Review date','date',plan?.due||'')}${field('assignedEvaluator','Reassessment evaluator','text',plan?.assignedEvaluator||'')}</div>${actions('Save plan')}</form>`);bindForm(async v=>{await mutate('remediation',{...v,planId:plan?.id});closeModal();toast('Remediation plan recorded')})}
function closePlan(id){showModal('Close remediation after reassessment',`<form id="activeForm">${area('evidence','Describe the successful reassessment and evidence reference')}${actions('Verify and close plan')}</form>`);bindForm(async v=>{await mutate('close-remediation',{planId:id,evidence:v.evidence});closeModal();toast('Remediation closed')})}
function releaseForm(){showModal('Final training release',`<form id="activeForm"><p class="notice">The system verifies every training gate and the current final exam before accepting this decision. Your signed-in identity and an immutable training snapshot will be retained.</p><div class="formgrid">${field('effectiveDate','Effective release date','date',new Date().toLocaleDateString('en-CA'))}${field('operationalApproval','Operational approval name and reference')}${field('clinicalApproval','Required clinical approval name and reference')}</div>${area('restrictions','Explicit restrictions or limitations','',false)}${area('notes','Final review and release decision')}${check('attest','I verify that the required operational and clinical approvals have been obtained.')}${actions('Authorize final release')}</form>`);bindForm(async v=>{await mutate('release',{...v,attest:v.attest==='on'});closeModal();toast('Final release recorded and training locked')})}
async function takeExam(){try{await mutate('start-exam');const e=data().activeExam;if(!e)return;showModal('Final knowledge assessment',`<p class="notice">${e.questions.length} questions · Passing score ${app.settings.passPercent}% with every safety-critical question correct. Answers are graded on the server. Answers save automatically while this form is open. Confirm the saved status before leaving.</p><form id="activeForm">${questionFields(e.questions,e.draftAnswers)}<p class="form-note" id="examSaveStatus" role="status">${e.savedAt?'Answers restored from '+esc(datetime(e.savedAt)):'No answers saved yet.'}</p><button type="button" onclick="saveExamProgress()">Save answers now</button>${actions('Submit final assessment')}</form>`,'TRAINEE FINAL ASSESSMENT');$('#activeForm').addEventListener('change',()=>{clearTimeout(examSaveTimer);examSaveTimer=setTimeout(()=>saveExamProgress(),600)});bindForm(async v=>{clearTimeout(examSaveTimer);await saveExamProgress(true);const answers=Object.fromEntries(e.questions.map(q=>[q.id,Number(v[q.id])])),result=await mutate('submit-exam',{attemptId:e.id,answers});showModal(result.result.passed?'Final assessment passed':'Assessment review required',`<h2>${result.result.score}%</h2><p>${result.result.passed?'The knowledge requirement is complete. Your administrator still records the final release.':'Review learning needs with your FTO. An administrator must approve another attempt.'}</p><button class="primary" onclick="closeModal()">Return to training</button>`);})}catch(e){toast(e.message)}}
async function manageExam(){try{editorExam=await request('/exam-bank');showExamEditor()}catch(e){toast(e.message)}}
function examEditorCapture(){const form=$('#activeForm');if(!form)return;const v=formValues(form);editorExam.passPercent=Number(v.passPercent);editorExam.published=v.published==='on';editorExam.questions=editorExam.questions.map((q,i)=>({...q,prompt:v['prompt'+i],options:[0,1,2,3].map(n=>v['option'+i+'_'+n]),correct:Number(v['correct'+i]),critical:v['critical'+i]==='on',levels:app.catalog.skills[0].levels.filter(l=>v['level'+i+'_'+l]==='on'),explanation:v['explanation'+i]}))}
function showExamEditor(){showModal('Final exam authoring',`<p class="notice">Review the questions and track assignments before publication. Saving creates a new exam version. Trainees must pass the current version before final release. Answer keys are available only to administrators.</p><form id="activeForm">${field('passPercent','Passing percentage','number',editorExam.passPercent)}${check('published','Publish this exam for approved trainees',editorExam.published)}${editorExam.questions.map((q,i)=>`<details class="details"><summary><span>Question ${i+1} · ${esc(q.prompt.slice(0,90))}</span>${badge(q.levels.join(' / '))}</summary>${area('prompt'+i,'Question',q.prompt)}<div class="formgrid">${q.options.map((o,n)=>field('option'+i+'_'+n,'Option '+(n+1),'text',o)).join('')}${select('correct'+i,'Correct answer',[[0,'Option 1'],[1,'Option 2'],[2,'Option 3'],[3,'Option 4']],q.correct)}</div>${check('critical'+i,'Safety-critical item — must be correct to pass',q.critical)}<div class="actions">${['EMT','AEMT','Paramedic'].map(l=>check('level'+i+'_'+l,l,q.levels.includes(l))).join('')}</div>${area('explanation'+i,'Answer rationale',q.explanation||'',false)}<button type="button" class="danger" onclick="examEditorCapture();editorExam.questions.splice(${i},1);showExamEditor()">Remove question</button></details>`).join('')}<button type="button" onclick="examEditorCapture();editorExam.questions.push({id:'custom-'+Date.now(),prompt:'',options:['','','',''],correct:0,critical:false,levels:['EMT','AEMT','Paramedic'],explanation:''});showExamEditor()">＋ Add question</button>${actions('Save exam version')}</form>`,'ADMINISTRATOR ONLY');bindForm(async()=>{examEditorCapture();await request('/exam-bank','POST',editorExam);await load();closeModal();toast('Exam version saved')})}
async function getInstructor(email){try{trainerEmail=email;trainerRecord=await request('/instructor/'+encodeURIComponent(email));if(page==='FTO academy')render()}catch(e){trainerRecord={error:e.message};if(page==='FTO academy')render()}}
function ftoView(){const members=admin()?(app.settings.members||[]).filter(m=>(m.roles||[m.role]).includes('trainer')&&m.active!==false):[{email:me().email,name:me().name}];if(!trainerEmail&&members.length){trainerEmail=members[0].email;getInstructor(trainerEmail)}const t=trainerRecord?.data;return heading('Train the trainer','FTO academy','Complete instruction, deliberate practice, calibration, mentored shifts, and documented appointment.',admin()&&members.length?`<select aria-label="FTO learner" onchange="trainerRecord=null;getInstructor(this.value)">${members.map(m=>`<option value="${esc(m.email)}" ${m.email===trainerEmail?'selected':''}>${esc(m.name||m.email)}</option>`).join('')}</select>`:'')+`<div class="hero"><div><div class="eyebrow">FIELD TRAINING OFFICER QUALIFICATION</div><h2>Teach consistently. Evaluate fairly.</h2><p>Eight taught modules totaling 16 hours, followed by a knowledge assessment, two mentored shifts, observed teaching and evaluation, and administrator appointment.</p></div><div class="hero-aside"><strong>16 h</strong><p>instructor-led course</p></div></div>${!members.length?'<p class="notice">The full instructor course is available below. Add a trainer account in Team and access when you are ready to enroll an FTO. No sample trainer has been created.</p>':trainerRecord?.error?`<p class="notice amber">${esc(trainerRecord.error)}</p>`:!t?'<p class="notice">Loading FTO qualification record…</p>':`<div class="stats">${stat('Lessons acknowledged',Object.keys(t.lessons).length+' / 8')}${stat('Verified attendance',t.attendance+' / 16 h')}${stat('Mentored shifts',t.mentoredShifts.length+' / 2')}${stat('Appointment',t.appointment?'Appointed':'Not appointed',t.appointment?'Expires '+t.appointment.expires:'Administrator decision required')}</div><div class="actions" style="margin-bottom:22px">${me().role==='trainer'?button('Take FTO knowledge assessment','instructorExam()','primary'):button('Verify attendance and observed assessments','instructorAssessment()')}${admin()?button('Record FTO appointment','appointInstructor()','primary'):''}</div>${t.examAttempts.length?card('FTO knowledge results',t.examAttempts.map(e=>`<p class="small">${esc(datetime(e.at))} · ${e.score}% · ${e.passed?'Passed':'Review required'}</p>`).join('')):''}` }${courseDownloads()}<div class="cards">${app.catalog.ftoModules.map(m=>`<section class="card lesson-card"><div class="eyebrow">${m.hours} INSTRUCTOR-LED HOURS</div><h2>${esc(m.title)}</h2><p>${esc(m.exercise)}</p><div class="wide-label">${badge(t?.lessons[m.id]?'Acknowledged':'Required',t?.lessons[m.id]?'green':'')}<button onclick="openFtoLesson(${arg(m.id)})">Open instruction →</button></div></section>`).join('')}</div>`}
function openFtoLesson(id){const m=app.catalog.ftoModules.find(m=>m.id===id);showModal(m.title,`<div class="reading"><h3>Facilitation schedule</h3><ul>${m.facilitation.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${m.sections.map(s=>`<h3>${esc(s.heading)}</h3><p>${esc(s.text)}</p>`).join('')}<div class="practice"><h3>Teaching and assessment exercise</h3><p>${esc(m.exercise)}</p></div><h3>Observed passing criteria</h3><ul>${m.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Every safety and integrity criterion must be satisfied. A failed exercise requires targeted instruction and a new assessment. A lesson acknowledgment does not establish the verified attendance or practical assessment.</p></div>${me().role==='trainer'?`<form id="activeForm">${area('reflection','What will you change in your teaching or evaluation practice?')}${actions('Acknowledge lesson')}</form>`:''}`,'FTO INSTRUCTOR AND LEARNER MATERIAL');if(me().role==='trainer')bindForm(async v=>{await request('/instructor/'+encodeURIComponent(me().email),'POST',{etag:trainerRecord.etag,action:'lesson',moduleId:id,reflection:v.reflection});await getInstructor(me().email);closeModal();toast('FTO lesson acknowledged')})}
async function instructorExam(){try{const r=await request('/instructor/'+encodeURIComponent(me().email),'POST',{etag:trainerRecord.etag,action:'questions'});showModal('FTO knowledge assessment',`<p class="notice">Passing requires 80% and every safety-critical item correct. The observed teaching and evaluation exercises are separate requirements.</p><form id="activeForm">${questionFields(r.questions)}${actions('Submit FTO assessment')}</form>`);bindForm(async v=>{const answers=Object.fromEntries(r.questions.map(q=>[q.id,Number(v[q.id])])),result=await request('/instructor/'+encodeURIComponent(me().email),'POST',{etag:trainerRecord.etag,action:'exam',answers});await getInstructor(me().email);showModal(result.result.passed?'FTO knowledge assessment passed':'Review and reassessment required',`<h2>${result.result.score}%</h2><p>Complete all course and observed requirements before appointment.</p><button onclick="closeModal()">Return to FTO academy</button>`)})}catch(e){toast(e.message)}}
function instructorAssessment(){const t=trainerRecord?.data;if(!t)return toast('Select a trainer.');showModal('Verify FTO course and practical assessments',`<form id="activeForm">${field('attendance','Verified instructor-led attendance hours','number',t.attendance)}<p class="form-note">Two mentored shifts are required. Provide actual dates, mentor names, and references to the observed teaching and evaluation evidence.</p>${[0,1].map(i=>`<h3>Mentored shift ${i+1}</h3><div class="formgrid">${field('date'+i,'Date','date',t.mentoredShifts[i]?.date||'')}${field('mentor'+i,'Mentor', 'text',t.mentoredShifts[i]?.mentor||'')}${field('reference'+i,'Observed-shift evidence reference','text',t.mentoredShifts[i]?.reference||'')}</div>`).join('')}${check('teachingPassed','Observed teaching exercise meets every required rubric criterion',t.teachingPassed)}${check('evaluationPassed','Observed evaluation and calibration exercise meets every required criterion',t.evaluationPassed)}${area('notes','Attendance and practical assessment verification',t.assessmentNotes||'')}${actions('Verify FTO assessments')}</form>`);bindForm(async v=>{await request('/instructor/'+encodeURIComponent(trainerEmail),'POST',{etag:trainerRecord.etag,action:'assessment',attendance:Number(v.attendance),mentoredShifts:[0,1].map(i=>({date:v['date'+i],mentor:v['mentor'+i],reference:v['reference'+i]})),teachingPassed:v.teachingPassed==='on',evaluationPassed:v.evaluationPassed==='on',notes:v.notes});await getInstructor(trainerEmail);closeModal();toast('FTO attendance and assessments verified')})}
function appointInstructor(){if(!trainerRecord?.data)return toast('Select a trainer.');const end=new Date();end.setFullYear(end.getFullYear()+1);showModal('Appoint a qualified FTO',`<p class="notice">The course, knowledge assessment, 16 attendance hours, two mentored shifts, and observed teaching/evaluation must all be complete. The account’s licensure and assigned trainees also limit evaluation authority.</p><form id="activeForm">${field('expires','Appointment expiration','date',end.toISOString().slice(0,10))}${area('notes','Appointment approval, authorized role, and limits')}${actions('Record appointment')}</form>`);bindForm(async v=>{await request('/instructor/'+encodeURIComponent(trainerEmail),'POST',{etag:trainerRecord.etag,action:'appoint',...v});await getInstructor(trainerEmail);closeModal();toast('FTO appointment recorded')})}
function legacy_reviewView(){const tasks=[];for(const p of app.people){const d=app.enrollments[p.id].data;for(const s of live(d.shifts)){if(s.status==='Submitted')tasks.push({p,s,type:'shift',title:'FTO shift evaluation'});if(s.traineeResponse?.status==='Submitted')tasks.push({p,s,type:'response',title:'Trainee shift response'});if(s.trainerFeedback?.status==='Submitted')tasks.push({p,s,type:'feedback',title:'Private FTO feedback'})}for(const c of live(d.credentials).filter(c=>!c.verified))tasks.push({p,c,type:'credential',title:c.title});for(const req of d.phaseRequests.filter(q=>q.phase===d.currentPhase&&!d.phaseReviews.some(r=>r.phase===q.phase&&r.at>q.at)))tasks.push({p,type:'phase',title:'Phase '+req.phase+' recommendation',req});}return heading('Administrator oversight','Review desk','Review submitted work, verify evidence, resolve deficiencies, and control advancement.',button('Refresh records','reloadApp()'))+`<div class="stats">${stat('Awaiting review',tasks.length)}${stat('Active trainees',app.people.filter(p=>!app.enrollments[p.id].data.release).length)}${stat('Open remediation',app.people.reduce((n,p)=>n+live(app.enrollments[p.id].data.remediation).filter(x=>!x.closed).length,0))}${stat('Finalized records',app.people.filter(p=>app.enrollments[p.id].data.release).length)}</div>`+card('Review queue',tasks.length?tasks.map(t=>row(t.title,t.p.name+' · '+(t.s?date(t.s.start):t.c?t.c.reference:date(t.req.at)),button('Review',`selectReview(${arg(t.p.id)},${arg(t.type)},${arg(t.s?.id||t.c?.id||'')})`,'primary'),badge('Submitted','amber'))).join(''):empty('No submitted items are awaiting review.'))+card('Training oversight',`<div class="tablewrap"><table><tr><th>Trainee</th><th>Pathway</th><th>Phase</th><th>Lesson checks</th><th>PQS</th><th>Record</th></tr>${app.people.map(p=>{const e=app.enrollments[p.id];return `<tr><td><strong>${esc(p.name)}</strong><br>${esc(p.license)}</td><td>${esc(p.pathway)}</td><td>${e.data.currentPhase}</td><td>${e.readiness.lessons.complete} / ${e.readiness.lessons.total}</td><td>${e.readiness.skills.filter(s=>s.complete).length} / ${e.readiness.skills.length}</td><td>${button('Open',`selected=${arg(p.id)};go('Overview')`)}</td></tr>`}).join('')}</table></div>`)}
function selectReview(id,type,record){selected=id;render();if(type==='credential')verifyCredential(record);else if(type==='phase')phaseReviewForm();else reviewForm(record,type)}
function verifyCredential(id){const c=data().credentials.find(c=>c.id===id);showModal('Verify '+c.title,`<p><strong>Evidence reference</strong><br>${esc(c.reference)}</p><p>Expiration: ${esc(c.expires||'No expiration supplied')}</p>${c.fileId?`<a class="button" href="/evidence/${encodeURIComponent(selected)}/${encodeURIComponent(c.fileId)}" onclick="downloadEvidence(${arg(c.fileId)},'credential-evidence');return false">Download evidence</a>`:''}<form id="activeForm">${area('notes','Verification performed and current validity confirmed')}${actions('Verify credential')}</form>`);bindForm(async v=>{await mutate('verify-credential',{credentialId:id,notes:v.notes});closeModal();toast('Credential verified')})}
async function reloadApp(){try{await load();toast('Records refreshed')}catch(e){toast(e.message)}}
function legacy_teamView(){return heading('Program administration','Team and access','Create real accounts, assign trainees, and control evaluator authority.',button('＋ Add trainee','personForm()','primary'))+card('Trainee enrollments',app.people.map(p=>row(p.name,p.license+' · '+p.pathway+' pathway · Start '+p.startDate,button('Edit profile',`personForm(${arg(p.id)})`)+button('Open training',`selected=${arg(p.id)};go('Overview')`))).join(''))+card('Signed-in account roles',`<p class="form-note">Owner administrator: ${esc('wolletnoah@gmail.com')}. Add each person’s REU sign-in email and assign their role below. Each person also needs access through the site’s Sharing settings; adding a role does not send an invitation.</p>${(app.settings.members||[]).map(m=>row(m.name||m.email,m.email+' · '+m.role+(m.role==='trainer'?' · '+m.license:'')+(m.active===false?' · Disabled':''),button('Edit role',`memberForm(${arg(m.email)})`)+(m.role==='trainer'?button('FTO qualification',`trainerRecord=null;trainerEmail=${arg(m.email)};page='FTO academy';getInstructor(trainerEmail)`):'')+(m.active!==false?button('Disable',`disableMember(${arg(m.email)})`,'danger'):''))).join('')||empty('No additional login roles have been assigned.')}<button onclick="memberForm()">＋ Add account role</button>`)}
function legacy_personForm(id){const p=app.people.find(p=>p.id===id);showModal(p?'Edit trainee profile':'Create trainee enrollment',`<form id="activeForm">${field('name','Full name','text',p?.name||'')}<div class="formgrid">${select('license','EMS license',['EMT','AEMT','Paramedic'],p?.license||'EMT')}${select('pathway','Training pathway',['Standard','Experienced'],p?.pathway||'Standard')}${field('startDate','Start date','date',p?.startDate||new Date().toLocaleDateString('en-CA'))}</div><p class="form-note">Existing training evidence prevents changing the license or hour rules for that enrollment. Experienced pathways require the documented entry assessment and retain competency and release requirements.</p>${actions('Save trainee profile')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'person',person:{...v,id:p?.id}});await load();closeModal();toast('Trainee profile saved')})}
function legacy_memberForm(email){const m=app.settings.members?.find(m=>m.email===email);showModal(m?'Edit account role':'Add signed-in account',`<form id="activeForm">${field('email','REU sign-in email','email',m?.email||'')}${field('name','Display name','text',m?.name||'')}${select('role','Role',[['trainee','Trainee'],['trainer','Field Training Officer'],['admin','Administrator']],m?.role||'trainee')}${select('traineeId','For a trainee account — linked profile',[['','Choose trainee'],...app.people.map(p=>[p.id,p.name])],m?.traineeId||'',false)}${select('license','For an FTO — evaluator licensure',[['','Choose licensure'],...['EMT','AEMT','Paramedic']],m?.license||'',false)}<h3>For an FTO — assigned trainees</h3>${app.people.map(p=>check('assigned-'+p.id,p.name,m?.assignedIds?.includes(p.id))).join('')}<p class="notice">FTOs must complete course qualification and administrator appointment before formal evaluations. Role assignment does not create a clinical authorization or grant site-sharing access.</p>${actions('Save account role')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'member',member:{...v,assignedIds:app.people.filter(p=>v['assigned-'+p.id]==='on').map(p=>p.id)}});trainerRecord=null;await load();closeModal();toast('Account role saved')})}
function disableMember(email){showModal('Disable account role',`<form id="activeForm"><p>Disable ${esc(email)} in the training program? Their records and history are retained.</p>${actions('Disable role')}</form>`);bindForm(async()=>{await request('/config','POST',{etag:app.configEtag,action:'deactivate-member',email});await load();closeModal();toast('Account role disabled')})}
function handbookView(){return heading('The complete program','Program handbook','Administration, training standards, evaluation, remediation, and release.',admin()?button('Download full program booklet','exportProgram()','primary'):'')+card('Program contents',app.catalog.handbook.map((h,i)=>`<details class="details" ${i===0?'open':''}><summary>${i+1}. ${esc(h.title)}</summary><div class="reading"><p>${esc(h.text)}</p></div></details>`).join(''))+card('Required training records',app.catalog.forms.map(f=>`<details class="details"><summary>${esc(f.title)}</summary><ul>${f.fields.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`).join(''))+card('Governing reference sources',app.catalog.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></p>`).join('')+'<p class="form-note">Verify the current local MCA adoption, scope authorization, device instructions, and required agency approvals. This is an agency field-training program, not initial EMS licensure education or an automatic continuing-education approval.</p>')}
function courseDownloads(){const docs=app.resources.filter(d=>d.category==='FTO train the trainer'&&d.available);return docs.length?card('FTO instructor course and assessments',docs.map(d=>row(d.title,d.format+(d.adminOnly?' · Restricted administrator copy':''),`<a class="button" href="/references/${encodeURIComponent(d.file)}" onclick="downloadReference(${arg(d.file)});return false">Download ↓</a>`)).join('')):''}
function resourcesView(){const docs=app.resources.filter(r=>r.available&&r.category!=='FTO train the trainer');return heading('Reference library','Resources','Teaching materials, course assessments and supporting references.',admin()?button('Manage reference access','referenceSettings()'):'')+courseDownloads()+card('Current learning materials',`<p class="small muted">Lessons, skill sheets, scenarios and the handbook form the online program. Clinical protocols and equipment instructions require agency review.</p><div class="actions">${button('Lessons',"go('Lessons')")}${button('Skills and PQS',"go('Skills and PQS')")}${button('Program handbook',"go('Program handbook')")}</div>`)+card('Historical and supporting documents',`<div class="notice amber">Historical files support review and do not override current approved standards.</div>${docs.length?docs.map(d=>row(d.title,d.category+' · '+d.format,`<a class="button" href="/references/${encodeURIComponent(d.file)}" onclick="downloadReference(${arg(d.file)});return false">Download reference ↓</a>`)).join(''):empty('No supporting reference files have been released to this account.')}`)}
function referenceSettings(){showModal('Reference-document access',`<form id="activeForm"><p class="form-note">Only release historical source documents after reviewing their accuracy and applicability. Completed training records remain administrator-only exports.</p>${app.resources.filter(d=>!d.adminOnly).map(d=>check('ref-'+d.id,d.title,app.settings.referenceRelease.includes(d.id))).join('')}${actions('Save reference access')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'references',ids:app.resources.filter(d=>!d.adminOnly&&v['ref-'+d.id]==='on').map(d=>d.id)});await load();closeModal();toast('Reference access updated')})}
function settingsView(){return heading('Program control','Program settings','Adopt the program, validate local clinical references, and manage assessments.')+`<div class="stats">${stat('Program version',app.catalog.version)}${stat('Trainee lessons',app.catalog.modules.length)}${stat('Skill sheets',app.catalog.skills.length)}${stat('FTO course','16 h')}</div>`+card('Program adoption',app.settings.adoption?`<p>${badge('Adopted','green')}</p><p><strong>${esc(app.settings.adoption.version)}</strong><br>${esc(app.settings.adoption.by)} · ${esc(datetime(app.settings.adoption.at))}</p><p>${esc(app.settings.adoption.notes)}</p><p class="small">Governing reference: ${esc(app.settings.adoption.protocolReference)}</p>${button('Record updated adoption review','adoptionForm()')}`:`<p class="small muted">Review the complete handbook, lessons, competency sheets, FTO course, and assessments. Formal release remains locked until you document agency adoption and required clinical review. The proposed hours and standards are configurable through a future version rather than changing evidence already assigned to an enrollment.</p>${button('Review and adopt program','adoptionForm()','primary')}`)+card('Final assessment control',`<p class="small">Current exam version ${app.settings.examVersion} · ${app.settings.examPublished?'Published':'Draft'} · Passing score ${app.settings.passPercent}% with all safety-critical items correct.</p>${button('Open exam authoring','manageExam()')}`)+card('Access and records',`<p class="small muted">Trainee and FTO accounts see only their assigned records. Confidential FTO feedback is restricted to the trainee and administrator. Submitted records retain correction history. Finalized records retain an immutable snapshot and can be reopened only by an administrator.</p><div class="actions">${button('Team and account roles',"go('Team and access')")}${button('Full program booklet','exportProgram()')}${selected?button('Archived training records','archivedRecords()'):''}</div>`)}
function adoptionForm(){showModal('Adopt the REU field training program',`<form id="activeForm"><p class="notice">This is the agency’s adoption record. Confirm the reviews and approvals actually obtained; the website does not itself grant clinical authority.</p>${check('standards','Agency leadership reviewed the pathways, hours, evaluation standards, and release process.')}${check('protocols','The current local MCA protocols and license-specific authorizations have been verified.')}${check('skills','All skill sheets and device instructions were reviewed for current accuracy and applicability.')}${check('assessments','Lessons, FTO assessments, scenarios, and final exam questions were reviewed.')}${check('records','Access, retention, reporting, and required approval responsibilities were reviewed.')}${field('protocolReference','Current local governing protocol version and reference')}${area('notes','Agency adoption and clinical review approval references')}${actions('Record program adoption')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'adopt',checks:Object.fromEntries(['standards','protocols','skills','assessments','records'].map(k=>[k,v[k]==='on'])),notes:v.notes,protocolReference:v.protocolReference});await load();closeModal();toast('Program adoption recorded')})}
function labelFor(k){return k.replace(/([A-Z])/g,' $1').replace(/^./,s=>s.toUpperCase())}
function download(content,name,mime='text/html'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function printable(title,body){return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:letter;margin:14mm}body{font:12px Arial;line-height:1.45;max-width:900px;margin:40px auto;color:#15263b}h1{font-size:26px}h2{font-size:19px;border-top:1px solid #ddd;padding-top:10px;margin-top:18px;break-after:avoid}h3{font-size:15px;break-after:avoid}table{width:100%;border-collapse:collapse;margin:15px 0}th,td{border:1px solid #ddd;padding:5px;text-align:left;vertical-align:top}th{background:#f2f4f7}pre{white-space:pre-wrap;font:inherit}p,li{orphans:3;widows:3}@media print{button{display:none}body{margin:0;max-width:none}}</style></head><body><header style="margin-bottom:18px;break-inside:avoid"><img src="data:image/png;base64," alt="Reading Emergency Unit — Hillsdale County Michigan — Established 1970" style="display:block;width:100%;height:auto"></header><button onclick="window.print()">Print or save as PDF</button><p>READING EMERGENCY UNIT · ${esc(app.catalog.version)}</p>${presentation?'<p><strong>DEMONSTRATION ONLY — Synthetic records. No real qualification or release authorization.</strong></p>':''}<h1>${esc(title)}</h1>${body}</body></html>`}
async function exportProgram(){if(!admin())return;const c=app.catalog,bank=await request('/exam-bank');const html=printable('Field Training and Evaluation Program',`<p>Version ${esc(c.version)} · ${app.settings.adoption?'Agency adoption recorded':'Draft for agency and clinical review'}</p>${c.handbook.map(h=>`<h2>${esc(h.title)}</h2><p>${esc(h.text)}</p>`).join('')}<h2>Trainee lessons</h2>${c.modules.map(m=>`<h2>${esc(m.id)} ${esc(m.title)}</h2><ul>${m.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>${m.sections.map(s=>`<h3>${esc(s.heading)}</h3><p>${esc(s.text)}</p>`).join('')}<h3>Practice</h3><p>${esc(m.practice)}</p>${m.questions.map(q=>`<p><strong>${esc(q.prompt)}</strong></p><ol>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol>`).join('')}`).join('')}<h2>FTO qualification course</h2>${c.ftoModules.map(m=>`<h2>${esc(m.id)} ${esc(m.title)} · ${m.hours} hours</h2><ul>${m.facilitation.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${m.sections.map(s=>`<h3>${esc(s.heading)}</h3><p>${esc(s.text)}</p>`).join('')}<h3>Exercise</h3><p>${esc(m.exercise)}</p><h3>Passing rubric</h3><ul>${m.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<h2>Personnel qualification standard and skill sheets</h2>${c.skills.map(s=>`<h2>${esc(s.id)} ${esc(s.title)}</h2><p>Applicable levels: ${esc(s.levels.join(', '))}</p><p>${esc(s.standard)}</p><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p><strong>Critical failure:</strong> ${esc(s.critical)}</p><p>${esc(s.remediation)}</p>`).join('')}<h2>Scenario assessments</h2>${c.scenarios.map(s=>`<h3>${esc(s.title)}</h3><p>${esc(s.setup)}</p><p><strong>Inject:</strong> ${esc(s.inject)}</p><p><strong>Expected performance:</strong> ${esc(s.expected)}</p><ul>${s.rubric.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<h2>Required record templates</h2>${c.forms.map(f=>`<h3>${esc(f.title)}</h3><table>${f.fields.map(x=>`<tr><th>${esc(x)}</th><td>________________________________________________</td></tr>`).join('')}</table>`).join('')}<h2>Administrator final exam bank and answer key</h2><p>Version ${bank.version}. Keep this appendix restricted to authorized administrators.</p>${[...bank.questions,...(bank.instructorQuestions||[])].map(q=>`<h3>${esc(q.prompt)}</h3><ol>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ol><p><strong>Correct:</strong> ${esc(q.options[q.correct])}${q.critical?' · Safety-critical':''}</p><p>${esc(q.explanation)}</p>`).join('')}`);download(html,'REU-complete-field-training-program.html');toast('Complete program booklet downloaded')}
function compactReportHTML(result){
 const d=result.record,p=result.person,r=result.release?.readiness||result.readiness;
 const table=(heads,rows)=>`<table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">No records recorded.</td></tr>`}</tbody></table>`;
 return printable('Compact training summary — '+p.name,`<p><strong>${esc(p.name)}</strong> · ${esc(p.license)} · ${esc(p.pathway)} · Version ${esc(d.version)}<br>Generated ${esc(datetime(new Date().toISOString()))}</p>
 <p><strong>${result.release?'Finalized training record':'In-progress training — not a release authorization'}</strong><br>This compact summary supports review. Consult the full training record for narratives, confidential feedback, assessment steps and audit history.</p>
 ${result.release?`<h2>Final authorization</h2><p>Recorded by ${esc(result.release.name)} · ${esc(datetime(result.release.at))}<br>Effective ${esc(result.release.effectiveDate)}<br>Clinical approval: ${esc(result.release.clinicalApproval)}<br>Operational approval: ${esc(result.release.operationalApproval)}<br>Restrictions: ${esc(result.release.restrictions||'None recorded')}</p>`:''}
 <h2>Phase progress</h2>${table(['Phase','Accepted / required hours','Decision'],r.hours.map(h=>[h.id+' · '+h.title,h.actual+' / '+h.required,h.approved?'Approved':'Pending']))}
 <p><strong>Lessons:</strong> ${r.lessons.complete} / ${r.lessons.total} · <strong>PQS:</strong> ${r.skills.filter(x=>x.complete).length} / ${r.skills.length} · <strong>Scenarios:</strong> ${r.scenarios.filter(x=>x.complete).length} / ${r.scenarios.length}<br><strong>Actual lead encounters:</strong> ${r.actualEncounters} · <strong>PCR reviews:</strong> ${r.pcrReviews} · <strong>Evaluators:</strong> ${r.evaluators}</p>
 <h2>Outstanding requirements</h2>${r.blockers.length?`<ul>${r.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>No training-readiness blockers recorded. Final examination and release approvals remain separate requirements.</p>'}
 <h2>Credentials and courses</h2>${table(['Requirement','Status'],r.credentials.map(x=>[x.title,x.complete?'Verified':'Outstanding']))}
 <h2>Shift and form index</h2>${table(['Shift','Phase / hours','FTO evaluation','Trainee response','Trainer feedback'],live(d.shifts).map(x=>[datetime(x.start),x.phase+' / '+x.hours,x.status,x.traineeResponse?.status||'Missing',x.trainerFeedback?.status||'Missing']))}
 <h2>Daily PQS signatures</h2>${table(['Shift','Checklist','Demonstrated / items','Trainee signature','FTO signature'],live(d.shifts).map(s=>[datetime(s.start),s.dailyPqs?.status||'Not started',(s.dailyPqs?.rows.filter(x=>x.outcome==='Demonstrated').length||0)+' / '+(s.dailyPqs?.rows.length||0),s.dailyPqs?.traineeSignature?.by||'Not signed',s.dailyPqs?.evaluatorSignature?.by||'Not signed']))}<h2>PQS status</h2>${table(['Competency','Evidence','Status'],r.skills.map(x=>[x.id,x.count+' / '+x.required,x.complete?'Qualified':'Incomplete']))}
 <h2>Remediation</h2>${table(['Plan','Status','Review date'],live(d.remediation).map(x=>[x.title,x.closed?'Closed':'Open',x.due||'Not recorded']))}
 <h2>Final examination</h2>${table(['Submitted','Version','Score','Outcome'],d.examAttempts.map(x=>[datetime(x.at),x.version,x.score+'%',!x.valid?'Readiness changed':x.passed?'Passed':'Review required']))}`);
}
async function legacy_downloadCompactReport(){if(!admin())return;try{const result=await request('/trainees/'+encodeURIComponent(selected)+'/report');download(compactReportHTML(result),'REU-'+result.person.name.replace(/[^a-z0-9]/gi,'-')+'-compact-summary.html');toast('Compact training summary downloaded')}catch(error){toast(error.message)}}
async function legacy_downloadReport(){try{const result=await request('/trainees/'+encodeURIComponent(selected)+'/report'),d=result.record,p=result.person,r=result.release?.readiness||result.readiness;const html=printable((result.release?'Finalized':'Progress')+' training record — '+p.name,`<p>${esc(p.license)} · ${esc(p.pathway)} · Assigned version ${esc(d.version)}</p>${result.release?`<p><strong>Final authorization:</strong> ${esc(result.release.name)} · ${esc(datetime(result.release.at))}<br>Effective ${esc(result.release.effectiveDate)}<br>Clinical approval: ${esc(result.release.clinicalApproval)}<br>Operational approval: ${esc(result.release.operationalApproval)}<br>Restrictions: ${esc(result.release.restrictions||'None recorded')}</p><p>${esc(result.release.notes)}</p>`:'<p>This record remains in progress and is not a release authorization.</p>'}<h2>Readiness</h2><table><tr><th>Requirement</th><th>Evidence</th></tr>${r.hours.map(h=>`<tr><td>Phase ${h.id} ${esc(h.title)}</td><td>${h.actual} / ${h.required} accepted hours · ${h.approved?'Approved':'Pending'}</td></tr>`).join('')}<tr><td>Actual lead encounters</td><td>${r.actualEncounters}</td></tr><tr><td>PCR reviews</td><td>${r.pcrReviews}</td></tr></table><h2>PQS qualifications</h2><table>${r.skills.map(s=>`<tr><th>${esc(s.id)}</th><td>${s.count} / ${s.required} · ${s.complete?'Qualified':'Incomplete'}</td></tr>`).join('')}</table><h2>Shift evaluations and trainee forms</h2>${live(d.shifts).map(s=>`<h3>${esc(datetime(s.start))} · Phase ${s.phase}</h3><p>${s.hours} eligible hours · ${esc(s.status)} · Evaluator ${esc(s.evaluatorName||s.evaluator)}</p><p><strong>Objectives:</strong> ${esc(s.objectives)}</p><p><strong>Coaching:</strong> ${esc(s.sharedFeedback)}</p><p><strong>Confidential notes:</strong> ${esc(s.privateNotes||'None.')}</p><table>${Object.entries(s.ratings).map(([k,v])=>`<tr><th>${esc(ratingLabels[k])}</th><td>${v??'Not observed'}</td></tr>`).join('')}</table><p><strong>Attestation:</strong> ${esc(s.attestation?.by||'Draft')} · ${esc(s.attestation?.at||'')}</p><h4>Encounter evidence</h4><table>${s.encounters.map(e=>`<tr><td>${esc(e.reference)}</td><td>${esc(e.role)} · ${e.actual?'Actual':'Simulation'} · ${e.independent?'Independent':'Coached'}</td><td>${e.pcrReviewed?'PCR reviewed':'No PCR review'}${e.substantiveCorrection?' · Substantive correction':''}</td></tr>`).join('')}</table>${['traineeResponse','trainerFeedback'].map(k=>s[k]?`<h4>${esc(labelFor(k))} · ${esc(s[k].status)}</h4>${Object.entries(s[k]).filter(([key])=>!['review'].includes(key)).map(([key,v])=>`<p><strong>${esc(labelFor(key))}:</strong> ${esc(v)}</p>`).join('')}`:'').join('')}`).join('')}<h2>Daily PQS check-off sheets</h2>${live(d.shifts).map(dailyPqsReport).join('')}<h2>Skill assessment evidence</h2>${live(d.skills).map(e=>`<h3>${esc(e.skillId)} · ${e.passed?'Successful':'Reassessment required'}</h3><p>${esc(e.reference)} · ${esc(e.mode)} · ${esc(e.evaluator)} · ${esc(e.at)}</p><p>${esc(e.notes)}</p><ol>${e.steps.map((v,i)=>`<li>${esc(app.catalog.skills.find(s=>s.id===e.skillId)?.steps[i]||'Step')} — ${esc(v)}</li>`).join('')}</ol>`).join('')}<h2>Phase decisions and remediation</h2>${d.phaseReviews.map(v=>`<p>Phase ${v.phase}: ${esc(v.decision)} · ${esc(v.by)} · ${esc(v.at)}<br>${esc(v.notes)}</p>`).join('')}${live(d.remediation).map(v=>`<h3>${esc(v.title)} · ${v.closed?'Closed':'Open'}</h3><p>${esc(v.deficiency)}</p><p>${esc(v.standard)}</p><p>${esc(v.instruction)}</p><p>${esc(v.closure?.evidence||'No closure recorded.')}</p>`).join('')}<h2>Final exam attempts</h2><table>${d.examAttempts.map(v=>`<tr><td>${esc(v.at)}</td><td>Version ${v.version}</td><td>${v.score}%</td><td>${!v.valid?'Readiness changed':v.passed?'Passed':'Review required'}</td></tr>`).join('')}</table><h2>Audit history</h2><table>${d.audit.map(v=>`<tr><td>${esc(v.at)}</td><td>${esc(v.actor)}</td><td>${esc(v.action)}</td></tr>`).join('')}</table>`);download(html,'REU-'+p.name.replace(/[^a-z0-9]/gi,'-')+'-'+(result.release?'final':'progress')+'-report.html');toast('Training report downloaded')}catch(e){toast(e.message)}}


function archivedRecords(){const collections=['shifts','credentials','remediation','skills','scenarios'];showModal('Archived records — '+person().name,collections.map(collection=>{const entries=data()[collection].filter(x=>x.archived);return entries.length?'<h3>'+esc(labelFor(collection))+'</h3>'+entries.map(x=>row(x.title||x.skillId||x.scenarioId||date(x.start),x.archived.reason,button('Restore',`restoreRecord(${arg(collection)},${arg(x.id)})`))).join(''):''}).join('')||empty('No archived training records.'))}
async function restoreRecord(collection,id){try{await mutate('restore',{collection,recordId:id});closeModal();toast('Record restored; readiness must be reviewed again')}catch(e){toast(e.message)}}

const demoNames=[['demo-orientation','Alex · Orientation'],['demo-field','Blake · Field training'],['demo-exam','Casey · Ready for exam'],['demo-complete','Drew · Finalized record']];
async function switchPresentation(role,id,next='Overview'){
 if(!['admin','trainer','trainee'].includes(role)||!demoNames.some(([key])=>key===id))return;
 if(roleSwitching)return;roleSwitching=true;
 const prior=presentation;presentation={role,trainee:id};
 try{
  const workspace=await request('/bootstrap');
  if(workspace.account.role!==role)throw Error('The requested access level could not be activated.');
  sessionStorage.setItem('reu-presentation',JSON.stringify(presentation));
  $('#app').innerHTML=`<div class="initial"><img src="./reu-patch.jpg" alt="REU"><h1>Switching to ${esc(role==='trainer'?'FTO':role==='admin'?'Admin':'Trainee')}</h1><p>Loading your complete workspace and permissions…</p></div>`;
  window.location.reload();
 }catch(error){presentation=prior;roleSwitching=false;toast(error.message)}
}
async function exitPresentation(){if(roleSwitching)return;roleSwitching=true;sessionStorage.removeItem('reu-presentation');window.location.reload()}
let roleSwitching=false;

function resetPresentation(){showModal('Reset test records',`<p>Restore the four sample trainees and their sample training records. This only resets your role-testing workspace.</p><form id="activeForm">${actions('Reset test records')}</form>`);bindForm(async()=>{await request('/presentation','POST',{action:'reset'});await switchPresentation('admin','demo-field','Overview');toast('Test records restored')})}
function presentationHeaders(){const realRole=sessionStorage.getItem('reu-active-role');return presentation?{'X-REU-Presentation':'1','X-REU-Presentation-Role':presentation.role,'X-REU-Presentation-Trainee':presentation.trainee}: (realRole?{'X-REU-Role':realRole}:{})}
async function downloadFile(path,name){try{const r=await fetch(path,{credentials:'same-origin',headers:presentationHeaders()});if(!r.ok){let e;try{e=await r.json()}catch{}throw Error(e?.error||'The file is unavailable.')}const blob=await r.blob(),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch(e){toast(e.message)}}
function downloadReference(file){return downloadFile('/references/'+encodeURIComponent(file),file)}
function downloadEvidence(id,name){return downloadFile('/evidence/'+encodeURIComponent(selected)+'/'+encodeURIComponent(id),name)}

let examSaveTimer=null,examSavePending=null;
async function saveExamProgress(throwOnError=false){if(examSavePending){try{await examSavePending}catch(e){if(throwOnError)throw e}}const e=data()?.activeExam,form=$('#activeForm'),status=$('#examSaveStatus');if(!e||!form||!status)return;const record=rec(),target=selected,values=formValues(form),answers=Object.fromEntries(e.questions.filter(q=>values[q.id]!==undefined).map(q=>[q.id,Number(values[q.id])]));status.textContent='Saving answers…';const task=request('/trainees/'+encodeURIComponent(target)+'/action','POST',{action:'save-exam',etag:record.etag,attemptId:e.id,answers});examSavePending=task;try{const result=await task;record.etag=result.etag;e.draftAnswers=answers;e.savedAt=result.savedAt;if(status.isConnected)status.textContent='Answers saved '+datetime(result.savedAt)}catch(error){if(status.isConnected)status.textContent='Answers not saved: '+error.message;if(throwOnError)throw error}finally{if(examSavePending===task)examSavePending=null}}

// Website activity, scheduled shifts and role-specific paperwork reminders.
let activityData=null,activityLoading=false,activityFilters={q:'',category:'',from:'',to:'',includeDemo:false};
let calendarData=null,calendarLoading=false,calendarFor=null,calendarMonth=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Detroit'}));calendarMonth.setDate(1);
let reminderData={due:[]},reminderLoading=false,nextReminderAt=0,sessionLogged=false;
const eastern=v=>new Intl.DateTimeFormat('en-US',{timeZone:'America/Detroit',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(v));
function browserEvent(action,detail={}){if(!app)return;request('/events','POST',{action,...detail}).catch(()=>{})}
function legacy_activityView(){if(!activityData&&!activityLoading)queueMicrotask(()=>loadActivity(false));return heading('Administrator only','Website activity log','Authenticated activity, access attempts, navigation, submissions, approvals and downloads.',button('Refresh log','loadActivity(false)'))+card('Search activity',`<form id="activityFilter" onsubmit="event.preventDefault();applyActivityFilters()"><div class="formgrid">${field('q','Search email, action or record path','search',activityFilters.q,false)}${select('category','Category',[['','All categories'],...['Authentication','Navigation','Forms','PQS','Assessments','Administration','Calendar','Security','Files','System']],activityFilters.category,false)}${field('from','From date UTC','date',activityFilters.from,false)}${field('to','Through date UTC','date',activityFilters.to,false)}</div>${check('includeDemo','Include demonstration activity',activityFilters.includeDemo)}<div class="actions"><button class="primary">Apply filters</button>${button('Export loaded entries','exportActivity()')}</div></form><p class="form-note">Events are append-only. Request bodies, form narratives, exam answers and private calendar links are excluded. Sign-in attempts blocked by ChatGPT before reaching this website are not available here.</p>`)+card('Recorded activity',activityData?.error?`<p class="notice amber">${esc(activityData.error)}</p>`:!activityData?empty('Loading activity history…'):`<p class="small muted">${activityData.events.length} entries loaded. Displayed times use your browser’s local timezone. Each request has an attempt entry and an outcome entry.</p><div class="tablewrap"><table><tr><th>Time</th><th>Account and role</th><th>Activity</th><th>Result</th><th>Details</th></tr>${activityData.events.map(e=>`<tr><td>${esc(datetime(e.at))}</td><td>${esc(e.actor_email)}<br><small>${esc(e.role)}</small></td><td>${esc(e.category)}<br><strong>${esc(e.action)}</strong>${e.demonstration?'<br><span class="badge amber">Demo</span>':''}</td><td>${esc(e.phase)}${e.status?' · '+e.status:''}</td><td><small>${esc(e.method+' '+e.path)}<br>${esc(Object.entries(e.details).map(([k,v])=>labelFor(k)+': '+v).join(' · '))}<br>Request ${esc(e.request_id.slice(0,8))}</small></td></tr>`).join('')}</table></div>${!activityData.events.length?empty('No activity matches these filters.'):''}${activityData.next?button('Load earlier entries','loadActivity(true)'):''}`)}
async function loadActivity(more=false){if(activityLoading)return;activityLoading=true;const q=new URLSearchParams();for(const key of ['q','category','from','to'])if(activityFilters[key])q.set(key,activityFilters[key]);if(activityFilters.includeDemo)q.set('includeDemo','1');if(more&&activityData?.next)q.set('before',activityData.next);try{const result=await request('/activity?'+q);activityData=more?{...result,events:[...activityData.events,...result.events]}:result}catch(e){activityData={error:e.message,events:[]}}finally{activityLoading=false;if(page==='Activity log')render()}}
function applyActivityFilters(){const v=formValues($('#activityFilter'));activityFilters={...v,includeDemo:v.includeDemo==='on'};activityData=null;loadActivity(false)}
function exportActivity(){if(!admin()||!activityData?.events?.length)return toast('Load activity entries first.');const cols=['at','actor_email','role','category','action','phase','status','method','path','demonstration','request_id'];const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const csv=[cols.join(','),...activityData.events.map(e=>cols.map(k=>cell(e[k])).join(','))].join('\r\n');download(csv,'REU-website-activity-loaded-entries.csv','text/csv');browserEvent('form-open',{title:'Activity log entries exported'})}
async function loadCalendar(){if(calendarLoading)return;calendarLoading=true;const target=selected;try{const result=await request('/calendar/'+encodeURIComponent(target));if(selected===target){calendarData=result;calendarFor=target}}catch(e){if(selected===target){calendarData={error:e.message,events:[]};calendarFor=target}}finally{calendarLoading=false;if(page==='Shift calendar')render()}}
function calendarView(){if(calendarFor!==selected&&!calendarLoading)queueMicrotask(loadCalendar);const d=calendarFor===selected?calendarData:null,year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),first=new Date(year,month,1),start=new Date(year,month,1-first.getDay()),todayKey=new Date().toLocaleDateString('en-CA',{timeZone:'America/Detroit'});const events=d?.events||[],labels=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const cells=Array.from({length:42},(_,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);const key=[day.getFullYear(),String(day.getMonth()+1).padStart(2,'0'),String(day.getDate()).padStart(2,'0')].join('-');const shifts=events.filter(e=>new Date(e.start).toLocaleDateString('en-CA',{timeZone:'America/Detroit'})===key);return `<div class="calendar-day ${day.getMonth()!==month?'outside':''} ${key===todayKey?'today':''}"><strong>${day.getDate()}</strong>${shifts.map(e=>`<button class="calendar-event" onclick="scheduledShift(${arg(e.id)})">${esc(new Intl.DateTimeFormat('en-US',{timeZone:'America/Detroit',hour:'numeric',minute:'2-digit'}).format(new Date(e.start)))}<br>${esc(e.title)}<br><small>${e.complete?'Forms submitted':Date.parse(e.end)<Date.now()?'Paperwork due':'Scheduled'}</small></button>`).join('')}</div>`}).join('');return heading('Aladtec and training','Shift calendar','Scheduled shifts connect to required forms. All calendar times are Eastern.',selectPerson())+card('Calendar connection',`<p>${d?.calendar?badge(d.calendar.connected?'Aladtec subscription connected':d.calendar.sourceType==='file'?'Imported ICS file':'Subscription disconnected','green'):'No calendar connected.'}</p><p class="small muted">${d?.calendar?.lastSync?'Last successful import: '+esc(datetime(d.calendar.lastSync)):''}</p>${d?.error||d?.calendar?.error?`<p class="notice amber">${esc(d.error||d.calendar.error)}</p>`:''}<div class="actions">${button('Connect Aladtec subscription','calendarConnectForm()','primary')}${button('Import ICS file','calendarFileForm()')}${d?.calendar?.connected?button('Sync now','syncCalendarNow()'):''}${button('Refresh calendar','refreshCalendarView()')}${button('Check paperwork reminders','previewShiftReminders()')}${d?.calendar?.connected&&(mine()||admin())?button('Disconnect subscription','disconnectCalendar()','danger'):''}</div><p class="form-note">Use the individual trainee’s subscription. The private link stays on the server. Imports cover the previous 90 and next 180 days. Connected feeds refresh about every 15 minutes while the academy is open.</p>`)+card('Scheduled shifts',`<div class="calendar-toolbar">${button('Previous month','moveCalendarMonth(-1)')}<h3>${esc(first.toLocaleDateString('en-US',{month:'long',year:'numeric'}))}</h3>${button('Next month','moveCalendarMonth(1)')}</div>${!d?empty('Loading scheduled shifts…'):`<div class="calendar-scroll"><div class="calendar-grid">${labels.map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${cells}</div></div>${!events.length?empty('Connect a subscription or import an ICS file to display this trainee’s shifts.'):''}`}`)+card('Forms awaiting completion',events.filter(e=>!e.complete&&Date.parse(e.end)<=Date.now()+3600000&&Date.parse(e.start)<=Date.now()).map(e=>row(e.title,eastern(e.start)+' – '+eastern(e.end)+' · '+e.missing.join(', '),button('Open shift paperwork',`scheduledShift(${arg(e.id)})`),badge(Date.parse(e.end)<Date.now()?'Overdue':'Final hour','amber'))).join('')||empty('No imported shifts currently need end-of-shift paperwork.'))}
function moveCalendarMonth(n){calendarMonth.setMonth(calendarMonth.getMonth()+n);render()}
function refreshCalendarView(){calendarFor=null;calendarData=null;loadCalendar()}
function calendarConnectForm(){showModal('Connect individual Aladtec calendar',`<p class="notice">In Aladtec, copy the trainee’s personal iCalendar subscription URL. This is a private subscription link, not the scheduler login-page address.</p><form id="activeForm">${field('url','Aladtec iCalendar subscription URL','password')}${check('individual','I confirm that this calendar contains only the selected trainee’s shifts.')}<p class="form-note">The link is used only to fetch the selected trainee’s REU schedule and is not returned to browser accounts or copied into the activity log.</p>${actions('Connect and import shifts')}</form>`);bindForm(async v=>{await request('/calendar/'+encodeURIComponent(selected),'POST',{action:'connect',url:v.url,individual:v.individual==='on'});calendarFor=null;await loadCalendar();closeModal();checkReminders(false);toast('Aladtec shifts imported')})}
function calendarFileForm(){showModal('Import trainee shift calendar',`<form id="activeForm"><label class="field">Aladtec ICS file *<input type="file" name="calendar" accept=".ics,text/calendar" required></label>${check('individual','I confirm that this file contains only the selected trainee’s shifts.')}<p class="form-note">An ICS upload is a snapshot. Reimport it to receive schedule changes, or connect a subscription for refreshes.</p>${actions('Import scheduled shifts')}</form>`);bindForm(async(v,form)=>{const file=form.elements.calendar.files[0];if(!file||file.size>1500000)throw Error('Choose an ICS file smaller than 1.5 MB.');const result=await request('/calendar/'+encodeURIComponent(selected),'POST',{action:'file',ics:await file.text(),individual:v.individual==='on'});calendarFor=null;await loadCalendar();closeModal();checkReminders(false);toast('Imported '+result.imported+' shifts'+(result.skipped?' · '+result.skipped+' all-day entries skipped':''))})}
async function syncCalendarNow(){try{await request('/calendar/'+encodeURIComponent(selected),'POST',{action:'sync'});calendarFor=null;await loadCalendar();checkReminders(false);toast('Calendar synchronized')}catch(e){toast(e.message)}}
function disconnectCalendar(){showModal('Disconnect calendar subscription',`<form id="activeForm"><p>Stop refreshing the private feed. Imported shifts and their paperwork remain available.</p>${actions('Disconnect subscription')}</form>`);bindForm(async()=>{await request('/calendar/'+encodeURIComponent(selected),'POST',{action:'disconnect'});calendarFor=null;await loadCalendar();closeModal();toast('Subscription disconnected')})}
function scheduledShift(id){const e=calendarData?.events.find(e=>e.id===id);if(!e)return;showModal(e.title,`<p><strong>${esc(eastern(e.start))} – ${esc(eastern(e.end))} Eastern</strong></p><p>${e.complete?'Your required forms have been submitted.':esc(e.missing.join(', '))}</p>${e.waitingForFto?'<p class="notice">The FTO must submit the evaluation before trainee response forms become available.</p>':''}<div class="actions">${button('View shift workspace',"closeModal();go('Shift workspace')",'primary')}${trainer()&&Date.parse(e.end)<=Date.now()&&!e.complete?button(e.shiftId?'Open recorded evaluation':'Create scheduled shift evaluation',e.shiftId?`closeModal();viewShift(${arg(e.shiftId)})`:`openScheduledEvaluation(${arg(e.id)})`):''}</div><p class="form-note">A scheduled shift does not count as training hours. Only actual documented training time and required approvals count.</p>`)}
function openScheduledEvaluation(id){const event=calendarData?.events.find(e=>e.id===id);if(event)openShift(null,event)}
function reminderScope(){return me()?.id+'|'+me()?.role+'|'+(presentation?.role||'real')+'|'+(presentation?.trainee||'')}
async function checkReminders(show=true){if(!app||reminderLoading||document.visibilityState!=='visible')return;const scope=reminderScope();reminderLoading=true;try{const result=await request('/reminders');if(scope!==reminderScope())return;reminderData=result;const banner=$('#shiftReminderBanner');if(banner)banner.innerHTML=reminderData.due.length?`<div class="shift-reminder"><div><strong>${reminderData.due.length} shift${reminderData.due.length===1?'':'s'} need paperwork</strong><p>Reminders begin one hour before shift end and remain until the required forms are submitted.</p></div>${button('View required forms','showShiftReminders()','primary')}</div>`:'';if(show&&!admin()&&reminderData.due.length&&Date.now()>=nextReminderAt&&!$('#modal').open)showShiftReminders()}catch(e){const banner=$('#shiftReminderBanner');if(banner)banner.innerHTML=`<p class="notice amber">Shift reminders could not refresh. ${esc(e.message)}</p>`}finally{reminderLoading=false;if(scope!==reminderScope())checkReminders(show)}}
function showShiftReminders(){nextReminderAt=Date.now()+10*60000;showModal('End-of-shift paperwork reminder',`${reminderData.due.map(e=>`<section class="reminder-item"><h3>${esc(e.trainee)} · ${e.overdue?'Shift ended':'Final hour'}</h3><p>${esc(e.title)}<br>Ends ${esc(eastern(e.end))} Eastern</p><p><strong>Required:</strong> ${esc(e.missing.join(', '))}</p>${e.waitingForFto?'<p class="small muted">Waiting for the FTO evaluation before trainee forms open.</p>':''}${button('Open shift paperwork',`openReminderShift(${arg(e.traineeId)},${arg(e.shiftId)})`,'primary')}</section>`).join('')}<p class="form-note">This reminder repeats about every 10 minutes while the academy is open and paperwork is outstanding. The banner stays visible. Saved drafts and returned forms remain outstanding.</p>${button('Remind me in 10 minutes','closeModal()')}`,'SHIFT COMPLETION');browserEvent('reminder-shown',{title:'End-of-shift paperwork reminder'})}
function openReminderShift(id,shiftId){selected=id;closeModal();go('Shift workspace');if(shiftId)viewShift(shiftId)}
setInterval(()=>checkReminders(true),60000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkReminders(true)});window.addEventListener('focus',()=>checkReminders(true));

startReuSession().catch(error=>{$('#app').innerHTML=`<div class="initial"><img src="./reu-patch.jpg" alt="REU"><h1>REU Field Training Academy</h1><p>${esc(error.message)}</p><button class="button primary" onclick="showReuLogin()">Sign in to REU</button><p class="small" style="margin-top:20px">Use the email assigned to your REU training account.</p></div>`});

function recordSignout(){fetch('/api/academy/events',{method:'POST',credentials:'same-origin',keepalive:true,headers:{...presentationHeaders(),'Content-Type':'application/json'},body:JSON.stringify({action:'signout-intent',page})}).catch(()=>{})}

async function previewShiftReminders(){try{reminderData=await request('/reminders');if(reminderData.due.length)showShiftReminders();else toast('No required shift paperwork is currently due for this role.')}catch(e){toast(e.message)}}

function legacy_roleSwitchBar(){if(!admin()&&!presentation)return '';return `<details class="role-tools"><summary>Current access: ${esc(me().role==='trainer'?'FTO':me().role==='admin'?'Admin':'Trainee')} <span>Switch role ▾</span></summary><section class="role-switch-bar" aria-label="Switch access level"><div><strong>Switch role</strong><small>${presentation?'Full role workspace · separate sample training records':'Use your existing login to test each access level'}</small></div><div class="role-switch-options">${[['admin','Admin'],['trainer','FTO'],['trainee','Trainee']].map(([role,label])=>`<button class="${(presentation?.role||me().role)===role?'selected':''}" aria-pressed="${(presentation?.role||me().role)===role?'true':'false'}" onclick="openRoleView(${arg(role)})">${label}</button>`).join('')}${presentation?'<button class="return-admin" onclick="exitPresentation()">Return to real Admin</button>':''}</div>${presentation?`<label class="small">Test trainee <select aria-label="Test trainee" onchange="switchPresentation(presentation.role,this.value)">${demoNames.map(([id,n])=>`<option value="${id}" ${presentation.trainee===id?'selected':''}>${n}</option>`).join('')}</select></label>${button('Reset test records','resetPresentation()')}`:''}</section></details>`}
async function openRoleView(role){if(!['admin','trainer','trainee'].includes(role))return;if($('#modal').open)closeModal();const id=presentation?.trainee||'demo-field';try{if(!presentation)await request('/presentation','POST',{action:'start'});await switchPresentation(role,id,'Overview')}catch(error){toast(error.message)}}

function dailyItems(s){return app.catalog.dailyPqs.phases.find(p=>p.phase===s.phase)?.items.filter(i=>i.levels.includes(person().license))||[]}
function dailyPqsView(){const shifts=live(data().shifts).slice().sort((a,b)=>b.start.localeCompare(a.start));return heading('Shift paperwork','Daily checklists','The trainee records shown/practiced items; the shift evaluator separately verifies performance under their own account.',selectPerson())+`<p class="notice">${esc(app.catalog.dailyPqs.note)} Signed daily sheets document exposure and performance; formal Skills and PQS qualification and final release remain separate.</p>`+dailyPqsFollowUp(shifts)+(!shifts.length?empty('Your FTO must create a training shift before you can complete its daily PQS sheet.'):shifts.map(s=>card(`${esc(date(s.start))} · ${esc(app.catalog.dailyPqs.phases.find(p=>p.phase===s.phase)?.title||'Phase '+s.phase)}`,`<p>${esc(s.evaluatorName||s.evaluator)} · ${esc(s.dailyPqs?.status||'Not started')}</p>${['Signed','Reviewed'].includes(s.dailyPqs?.status)?`<p class="small">Demonstrated: ${s.dailyPqs.rows.filter(x=>x.outcome==='Demonstrated').length} / ${s.dailyPqs.rows.length} · Follow-up: ${s.dailyPqs.rows.filter(x=>['Needs practice','Not observed'].includes(x.outcome)).length}</p>`:''}${button(mine()?'Complete / view daily PQS':'Review / sign daily PQS',`openDailyPqs(${arg(s.id)})`,'primary')}`)).join(''))}
function dailySignature(signature){return signature?`${esc(signature.name)} · ${esc(signature.by)} · ${esc(datetime(signature.at))}`:'Not signed'}
function openDailyPqs(id){const s=data().shifts.find(s=>s.id===id),sheet=s?.dailyPqs;if(!s)return;const items=dailyItems(s),editable=!data().release&&mine()&&(!sheet||['Draft','Returned'].includes(sheet.status)),canSign=!data().release&&trainer()&&sheet?.status==='Submitted'&&(admin()||s.evaluator===me().email),canReturn=!data().release&&admin()&&['Submitted','Signed'].includes(sheet?.status)&&(admin()||s.evaluator===me().email);
showModal('Daily PQS · '+date(s.start),`<p><strong>${esc(app.catalog.dailyPqs.phases.find(p=>p.phase===s.phase)?.title)}</strong><br>Shift: ${esc(datetime(s.start))} – ${esc(datetime(s.end))}<br>Checklist: ${esc(sheet?.status||'Not started')} · Revision ${sheet?.revision||1}</p><p class="notice">Shown = instructed or demonstrated to you. Practiced = you personally operated, performed or explained the item as appropriate. FTO outcomes describe observed performance; Not observed is not a pass. Use approved scope and device/protocol standards. Do not enter patient identifiers.</p>${sheet?.returnReason?`<p class="notice amber">Returned for correction: ${esc(sheet.returnReason)}</p>`:''}<form id="activeForm"><input type="hidden" name="intent" value="submit">${items.map(item=>{const row=sheet?.rows.find(r=>r.id===item.id)||{};return `<section class="pqs-item"><div class="eyebrow">${esc(item.group)} · ${esc(item.id)}</div><h3>${esc(item.title)}</h3>${editable?`<div class="formgrid">${select('shown-'+item.id,'Was this shown / explained to you?',[['','Choose'],['yes','Yes'],['no','No']],row.shown===true?'yes':row.shown===false?'no':'',false)}${select('practiced-'+item.id,'Did you operate / practice / explain it?',[['','Choose'],['yes','Yes'],['no','No']],row.practiced===true?'yes':row.practiced===false?'no':'',false)}</div>${area('notes-'+item.id,'Trainee notes / opportunity still needed',row.traineeNotes||'',false)}`:`<p class="small"><strong>Trainee shown:</strong> ${row.shown===true?'Yes':row.shown===false?'No':'Not answered'} · <strong>Practiced:</strong> ${row.practiced===true?'Yes':row.practiced===false?'No':'Not answered'}<br>${esc(row.traineeNotes||'')}</p>`}${mine()?'':canSign?`${select('outcome-'+item.id,'FTO observed outcome',[['','Choose'],['Demonstrated','Demonstrated successfully'],['Needs practice','Performed — needs practice'],['Not observed','Not observed / no opportunity'],['Not applicable','Not applicable — explain why']],row.outcome||'',false)}${area('fto-notes-'+item.id,'FTO notes / next practice plan',row.evaluatorNotes||'',false)}`:`<p class="small"><strong>FTO outcome:</strong> ${esc(row.outcome||'Awaiting evaluator')}<br>${esc(row.evaluatorNotes||'')}${row.evaluatorSignature?`<br>Signed: ${dailySignature(row.evaluatorSignature)}`:''}</p>`}</section>`}).join('')}<p class="small"><strong>Trainee signature:</strong> ${dailySignature(sheet?.traineeSignature)}${mine()?'':`<br><strong>Evaluator signature:</strong> ${dailySignature(sheet?.evaluatorSignature)}`}</p>${editable?`${check('attest','I confirm that my shown/practiced responses accurately describe this shift.')}<p class="form-error" id="formError" role="alert"></p><div class="form-actions"><button type="button" onclick="closeModal()">Close</button><button type="submit" formnovalidate onclick="this.form.elements.intent.value='save'">Save draft</button><button class="primary" onclick="this.form.elements.intent.value='submit'">Sign and submit to FTO</button></div>`:canSign?`${check('attest','I personally evaluated these items and attest that each recorded outcome is accurate. My signature confirms the recorded outcome; it does not turn unobserved items into passes.')}${actions('Sign evaluated items')}`:'<button type="button" onclick="closeModal()">Close</button>'}</form>${canReturn?`<div class="actions" style="margin-top:18px">${button('Return for correction',`returnDailyPqs(${arg(id)})`)}</div>`:''}`,'REU DAILY PQS');
if(editable)bindForm(async v=>{await mutate(v.intent==='save'?'daily-pqs-save':'daily-pqs-submit',{shiftId:id,attest:v.attest==='on',rows:items.map(i=>({id:i.id,shown:v['shown-'+i.id]==='yes'?true:v['shown-'+i.id]==='no'?false:null,practiced:v['practiced-'+i.id]==='yes'?true:v['practiced-'+i.id]==='no'?false:null,notes:v['notes-'+i.id]}))});closeModal();toast(v.intent==='save'?'Daily PQS draft saved':'Daily PQS submitted to FTO')});
if(canSign)bindForm(async v=>{await mutate('daily-pqs-sign',{shiftId:id,attest:v.attest==='on',rows:items.map(i=>({id:i.id,outcome:v['outcome-'+i.id],notes:v['fto-notes-'+i.id]}))});closeModal();toast('Daily PQS signed under your evaluator account')});
}
function legacy_returnDailyPqs(id){showModal('Return daily PQS for correction',`<form id="activeForm"><p>The previous trainee responses and evaluator signatures will remain in the administrator history. Resubmission requires new signatures.</p>${area('notes','Reason and required corrections')}${actions('Return checklist')}</form>`);bindForm(async v=>{await mutate('daily-pqs-return',{shiftId:id,notes:v.notes});closeModal();toast('Daily PQS returned; prior revision retained')})}
function dailyPqsReport(s){const q=s.dailyPqs;return `<h3>Daily PQS · ${esc(date(s.start))} · Phase ${s.phase}</h3>${!q?'<p>No daily checklist recorded for this shift.</p>':`<p>Status: ${esc(q.status)} · Revision ${q.revision}<br>Source: ${esc(q.source)} · ${esc(q.version)}<br>Trainee: ${dailySignature(q.traineeSignature)}<br>Evaluator: ${dailySignature(q.evaluatorSignature)}</p><table><thead><tr><th>PQS item</th><th>Shown / practiced</th><th>FTO outcome and signature</th></tr></thead><tbody>${q.rows.map(x=>`<tr><td>${esc(x.id+' · '+x.title)}</td><td>${x.shown===true?'Yes':x.shown===false?'No':'Unanswered'} / ${x.practiced===true?'Yes':x.practiced===false?'No':'Unanswered'}<br>${esc(x.traineeNotes)}</td><td>${esc(x.outcome||'Pending')}<br>${esc(x.evaluatorNotes||'')}<br>${dailySignature(x.evaluatorSignature)}</td></tr>`).join('')}</tbody></table>${(q.history||[]).length?`<h4>Retained revisions</h4>${q.history.map(h=>`<p>Returned ${esc(datetime(h.at))} by ${esc(h.by)}: ${esc(h.reason)}</p>${dailyPqsReport({start:s.start,phase:s.phase,dailyPqs:h.snapshot})}`).join('')}`:''}`}`}

function dailyPqsFollowUp(shifts){const latest=new Map();for(const s of shifts.slice().reverse())if(['Signed','Reviewed'].includes(s.dailyPqs?.status))for(const row of s.dailyPqs.rows)latest.set(row.id,row);const pending=[...latest.values()].filter(x=>['Needs practice','Not observed'].includes(x.outcome));return pending.length?card('Items needing follow-up',`<ul>${pending.map(x=>`<li><strong>${esc(x.title)}</strong> — ${esc(x.outcome)}${x.evaluatorNotes?' · '+esc(x.evaluatorNotes):''}</li>`).join('')}</ul><p class="small muted">These remain visible until a later signed checklist records successful demonstration. A signed sheet is not an automatic competency qualification.</p>`):''}

function pageLabel(name){return ({Overview:'Home','Training hub':'Training','Shift workspace':'Shift paperwork','Daily PQS':'Daily checklists','Shift calendar':'Calendar','Skills and PQS':'Practical skills','Final assessment':'Progress and downloads','Team and access':'People and access','Program handbook':'Handbook'})[name]||name}
function navGroup(name){if(['Shift workspace','Daily PQS'].includes(name))return 'shift';if(['Training hub','Training path','Lessons','Skills and PQS','Scenarios','Final assessment'].includes(name))return 'training';if(['Resources','Program handbook'].includes(name))return 'resources';if(['Review desk','Team and access','Activity log','Program settings'].includes(name))return 'admin';return name}
function legacy_sidebarNavigation(){const item=(name,ico,label)=>`<button class="${(page===name||(['Training hub','Shift workspace','Resources'].includes(name)&&navGroup(page)===navGroup(name)))?'active':''}" ${(page===name||(['Training hub','Shift workspace','Resources'].includes(name)&&navGroup(page)===navGroup(name)))?'aria-current="page"':''} onclick="go(${arg(name)})">${icon(ico)}${esc(label||pageLabel(name))}</button>`;return item('Overview','grid')+item('Shift workspace','shift')+item('Training hub','path')+item('Shift calendar','shift')+item('Resources','file')+(!mine()?`<div class="nav-label">INSTRUCTOR</div>${item('FTO academy','book','FTO qualification')}`:'')+(admin()?`<details class="admin-navigation" ${navGroup(page)==='admin'?'open':''}><summary>Administration</summary>${[['Review desk','check','Review forms'],['Team and access','people','People and access'],['Activity log','file','Activity log'],['Program settings','settings','Program settings']].map(x=>item(...x)).join('')}</details>`:'')}
function legacy_sectionNavigation(){const group=navGroup(page),items=group==='shift'?[['Shift workspace','Evaluations and forms'],['Daily PQS','Daily checklists']]:group==='training'?[['Training hub','Current day'],['Lessons','Lessons'],['Skills and PQS','Practical skills'],['Scenarios','Scenarios'],['Final assessment',admin()?'Progress and downloads':'My progress'],['Training path','Full pathway']]:group==='resources'?[['Resources','Resource files'],['Program handbook','Program handbook']]:[];return items.length?`<nav class="section-navigation" aria-label="Section navigation">${button('← Home',"go('Overview')",'section-home')}${items.map(([name,label])=>`<button class="${page===name?'selected':''}" ${page===name?'aria-current="page"':''} onclick="go(${arg(name)})">${esc(label)}</button>`).join('')}</nav>`:''}
function homeTile(title,description,label,action,ico){return `<section class="home-tile">${icon(ico)}<h2>${esc(title)}</h2><p>${esc(description)}</p>${button(esc(label),action)}</section>`}
function legacy_trainingHub(){const p=person(),d=data(),phase=app.catalog.phases.find(x=>x.id===d.currentPhase),lessons=app.catalog.modules.filter(x=>x.phase===phase.id&&x.levels.includes(p.license)),done=lessons.filter(x=>d.lessons[x.id]?.passed).length;return heading('Your current training day','Phase '+phase.id+' · '+phase.title,'Work through the goals with your FTO, then record your experience in the daily checklist.',selectPerson())+card(esc(phase.reuLabel||phase.title),`<p>${esc(phase.goal)}</p><ul>${(phase.reuFocus||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions">${button('Open daily checklist',"go('Daily PQS')",'primary')}${button('View shift paperwork',"go('Shift workspace')")}</div>`)+card('Lessons for this phase',`<p class="small muted">${done} of ${lessons.length} completed</p>${lessons.map(m=>row(m.title,d.lessons[m.id]?.passed?'Knowledge check passed':'Read, practice with your FTO and complete the knowledge check.',button(mine()?'Open lesson':'Review lesson',`openLesson(${arg(m.id)})`),badge(d.lessons[m.id]?.passed?'Complete':'To do',d.lessons[m.id]?.passed?'green':'amber'))).join('')}`)+`<div class="home-actions">${homeTile('Daily checklist','What you were shown, what you practiced, and your FTO’s signed evaluation.','Open daily checklists',"go('Daily PQS')",'check')}${homeTile('Practical qualifications','Detailed performance criteria and recorded skills assessments.','Open practical skills',"filter=String(data().currentPhase);go('Skills and PQS');filter=String(data().currentPhase);render()",'shield')}${homeTile('Full training pathway','View all five phases, hour requirements and advancement decisions.','View full pathway',"go('Training path')",'path')}</div>`}

function returnDailyPqs(id){reviewReuForm(selected,id,'pqs')}

// REU workspaces: all controls call server-authorized actions.
function reuRoleName(role){return {admin:'Admin',trainer:'FTO',trainee:'Trainee'}[role]||role}
function roleSwitchBar(){return `<details class="role-tools"><summary>Current access: ${esc(reuRoleName(me().role))}<span>Switch role ▾</span></summary><div class="cardbody"><p class="small">Your assigned workspaces</p><div class="actions">${(me().roles||[me().role]).map(role=>button(reuRoleName(role),`switchRealRole(${arg(role)})`,me().role===role?'primary':'')).join('')}</div>${admin()||presentation?`<hr><p class="small">Role demonstration — separate sample records</p><div class="actions">${[['admin','Admin'],['trainer','FTO'],['trainee','Trainee']].map(([r,n])=>button(n+' test view',`openRoleView(${arg(r)})`)).join('')}${presentation?button('Return to real Admin','returnRealAdmin()'):''}</div>`:''}</div></details>`}
function switchRealRole(role){if(!(me().roles||[]).includes(role))return;sessionStorage.setItem('reu-active-role',role);sessionStorage.removeItem('reu-presentation');window.location.reload()}
function returnRealAdmin(){sessionStorage.setItem('reu-active-role','admin');sessionStorage.removeItem('reu-presentation');window.location.reload()}
function navItems(){const list=[['Overview','grid'],['Training hub','path'],['Shift workspace','shift'],['Daily PQS','check'],['Shift calendar','shift'],['Resources','file'],['Program handbook','book']];if(!mine())list.push(['Training path','path'],['Lessons','book'],['Skills and PQS','check'],['Scenarios','shield'],['Final assessment','file'],['FTO academy','book'],['Concerns','shield']);if(admin())list.push(['Onboarding','people'],['Review desk','check'],['Team and access','people'],['Activity log','file'],['Program settings','settings']);return list}
function sidebarNavigation(){const items=[['Overview','Home','grid'],['Shift workspace','Shift paperwork','shift'],['Training hub','Training','path'],['Shift calendar','Calendar','shift'],['Resources','Resources','file']];if(!mine())items.push(['Concerns','Training concerns','shield'],['FTO academy','FTO qualification','book']);if(admin())items.push(['Onboarding','Pre-ride onboarding','people'],['Review desk','Review and corrections','check'],['Team and access','People and FTO assignments','people'],['Final assessment','Records and test-out','file'],['Activity log','Website activity','file'],['Program settings','Program settings','settings']);const adminPages=['Onboarding','Review desk','Team and access','Final assessment','Activity log','Program settings'];const render=([key,label,i])=>`<button class="${page===key?'active':''}" onclick="go(${arg(key)})">${icon(i)}${esc(label)}</button>`;return items.filter(x=>!adminPages.includes(x[0])).map(render).join('')+(admin()?`<details class="admin-navigation" ${adminPages.includes(page)?'open':''}><summary>Administration</summary>${items.filter(x=>adminPages.includes(x[0])).map(render).join('')}</details>`:'');/* legacy renderer */return items.map(([key,label,i])=>`<button class="${page===key?'active':''}" onclick="go(${arg(key)})">${icon(i)}${esc(label)}</button>`).join('')}
function sectionNavigation(){if(page==='Overview')return '';if(mine())return ['Shift workspace','Daily PQS'].includes(page)?`<nav class="section-navigation">${button('← Home',"go('Overview')")}${button('My shift forms',"go('Shift workspace')")}${button('My daily checklists',"go('Daily PQS')")}</nav>`:'';return `<nav class="section-navigation">${button('← Home',"go('Overview')")}${button('Current training day',"go('Training hub')")}${button('Shift paperwork',"go('Shift workspace')")}${button('Daily checklists',"go('Daily PQS')")}${admin()?button('Records and downloads',"go('Final assessment')"):''}</nav>`}
function reuSelect(id,next){selected=id;go(next)}
function reuStatus(){return rdy()?.status||'Pre-ride onboarding'}
function reuSummaryRow(p){const d=app.enrollments[p.id].data,status=app.enrollments[p.id].readiness.status;return row(p.name,p.license+' · '+status+' · '+(d.assignment?.ftoName||'No FTO assigned'),button('Open trainee',`reuSelect(${arg(p.id)},'Onboarding')`))}
function overview(){if(admin()){let submitted=0,overdue=0,concerns=0,corrections=0;for(const p of app.people){const d=app.enrollments[p.id].data;for(const s of live(d.shifts)){for(const f of reuFormList(s)){if(['Submitted','Signed'].includes(f.record?.status))submitted++;if(Date.now()>Date.parse(s.end)+12*3600000&&!['Submitted','Signed','Reviewed'].includes(f.record?.status))overdue++;}}concerns+=(d.concerns||[]).filter(x=>x.status!=='Cleared').length;corrections+=(d.corrections||[]).filter(x=>x.status==='Open').length;}return heading('Training Officer / Admin','Welcome, '+me().name.split(' ')[0],'Support your team, celebrate progress, and keep training moving.')+`<div class="stats">${stat('Forms awaiting approval',submitted)}${stat('Overdue forms',overdue,'More than 12 hours after shift end')}${stat('Open training concerns',concerns)}${stat('Correction requests',corrections)}</div>`+card('Your review starts here',`<div class="actions">${button('Review forms and correction requests',"go('Review desk')",'primary')}${button('Review training holds',"go('Concerns')")}</div>`)+card('Pre-ride onboarding',app.people.filter(p=>!app.enrollments[p.id].data.onboarding?.clearance).map(reuSummaryRow).join('')||empty('Everyone is up to date. New hires will appear here when added.'))+card('Active trainees',app.people.filter(p=>app.enrollments[p.id].data.onboarding?.clearance&&!app.enrollments[p.id].data.release).map(reuSummaryRow).join('')||empty('Your active trainees will appear here once they are cleared and assigned.'))+card('Final test-out',`<p>Written and practical assessments: <strong>Not yet developed</strong>. Both will require your assessment and a second reviewer before final release.</p>${app.people.filter(p=>app.enrollments[p.id].data.testRecommendation).map(p=>row(p.name,'FTO recommended final test-out',button('Review record',`reuSelect(${arg(p.id)},'Final assessment')`))).join('')}`)+card('Records and downloads',button('Open training records',"go('Final assessment')")+button('Website activity log',"go('Activity log')"));}
if(!person())return heading('REU training','Welcome, '+me().name.split(' ')[0],'No trainee is currently assigned to this workspace. An Admin manages assignments.');const d=data();return heading('Your REU workspace','Welcome, '+me().name.split(' ')[0],mine()?'Your next steps, your progress, and the support to get there.':'Help your assigned trainee build confidence, one shift at a time.',selectPerson())+card(esc(reuStatus()),`<p>Current day / phase: ${d.currentPhase}<br>Assigned FTO: ${esc(d.assignment?.ftoName||'Awaiting assignment after first-ride clearance')}<br>Next scheduled shift: ${esc(datetime(d.assignment?.firstShift))}</p>${d.onboarding?.clearance?'':'<p>Your Training Officer handles one-on-one pre-ride onboarding before FTO assignment.</p>'}<div class="actions">${button('Current training day',"go('Training hub')",'primary')}${button('Shift paperwork',"go('Shift workspace')")}${button('Daily PQS',"go('Daily PQS')")}</div>`)+(!d.onboarding?.clearance?onboardingView():card('Your next steps',`<p>Complete your daily checklist, response/driving log and evaluation of the trainer after each shift.</p><div class="actions">${button('Open my shift forms',"go('Shift workspace')",'primary')}${button('Open daily checklists',"go('Daily PQS')")}</div>`))}
function legacy_onboardingView(){const d=data(),o=d.onboarding||{items:{}};return heading('Before the first training ride','Pre-ride onboarding','HR release → one-on-one training → Admin clearance → FTO assignment and scheduling.',selectPerson())+card('Required preparation',Object.entries(app.workflow.onboarding).map(([key,label])=>row(label,o.items[key]?'Completed '+datetime(o.items[key].at):key==='map'?'Layout draft available for Admin review; the website assessment is not yet active.':'Pending',admin()?(['im','cevo'].includes(key)?button('Open fillable PDF',`openOnboardingPdf(${arg(key)})`):key==='map'?button('Preview map test draft',`openOnboardingPdf('map')`)+button('Admin answer key',`openOnboardingPdf('map-key')`):'')+(!o.clearance?button('Verify actual completion',`onboardingForm(${arg(key)})`):''):'',badge(o.items[key]?'Complete':'Pending',o.items[key]?'green':'amber'))).join(''))+card('First-ride clearance',o.clearance?`<p>Approved by ${esc(o.clearance.name)} on ${esc(datetime(o.clearance.at))}</p>${admin()?button('Revoke clearance',`decision('revoke-clearance','Revoke first-ride clearance','Explain why this clearance is being withdrawn.')`):''}`:admin()?button('Review and clear for first ride',`decision('clear-first-ride','Clear for first ride','Confirm all actual pre-ride requirements, including the map assessment, are complete.')`,'primary'):'<p>Awaiting administrator clearance.</p>')+(admin()?card('Trainer and schedule',`<p>${esc(d.assignment?.ftoName||'Not assigned')} · ${esc(datetime(d.assignment?.firstShift))}</p>${o.clearance?button('Assign / change approved FTO','assignmentForm()','primary'):'<p>FTO assignment is available after first-ride clearance.</p>'}`):'')}
function legacy_onboardingForm(item){showModal(app.workflow.onboarding[item],`<form id="activeForm"><p>Record only completed training. Do not upload medical fit-test questionnaires or patient information. A completion certificate/reference is sufficient.</p>${field('reference','Completion date and evidence reference')}${item==='map'?check('external','I verified an actual externally completed map/area assessment. The website test is not yet developed.'):''}${actions('Verify completion')}</form>`);bindForm(async v=>{await mutate('onboarding-item',{item,reference:v.reference,completed:true,external:v.external==='on'});closeModal()})}
function assignmentForm(){const eligible=app.approvedFtos.filter(f=>['EMT','AEMT','Paramedic'].indexOf(f.license)>=['EMT','AEMT','Paramedic'].indexOf(person().license));showModal('Assign primary or covering FTO',`<form id="activeForm">${select('email','Approved FTO',[['','Select approved FTO'],...eligible.map(f=>[f.email,f.name+' · '+f.license])],data().assignment?.ftoEmail||'')}${field('firstShift','First / next training shift','datetime-local','')}${area('notes','Assignment reason — primary, sick coverage, time off or schedule change')}<p>Only active, appointed FTOs qualified for this license are listed. Reassignment removes the previous FTO’s access while retaining their signed records.</p>${actions('Save FTO assignment')}</form>`);bindForm(async v=>{await mutate('assign-fto',{...v,firstShift:new Date(v.firstShift).toISOString()});closeModal()})}
function teamView(){return heading('Accounts and assignments','People and access','A person may have multiple roles. Every Admin has the same access.',button('Add trainee','personForm()','primary'))+card('Trainees',app.people.map(p=>row(p.name,p.license,button('Onboarding / FTO assignment',`reuSelect(${arg(p.id)},'Onboarding')`)+button('Edit trainee',`personForm(${arg(p.id)})`))).join(''))+card('Account roles',button('Add account','memberForm()')+(app.settings.members||[]).map(m=>row(m.name,(m.roles||[m.role]).map(reuRoleName).join(' + '),button('Edit roles',`memberForm(${arg(m.email)})`))).join(''))}
function memberForm(email){const m=app.settings.members?.find(m=>m.email===email),roles=m?.roles||[m?.role];showModal('Account roles',`<form id="activeForm">${field('email','REU sign-in email','email',m?.email||'')}${field('name','Name','text',m?.name||'')}${['admin','trainer','trainee'].map(r=>check(r,reuRoleName(r),roles.includes(r))).join('')}${select('license','FTO license level',[['','Choose'],...['EMT','AEMT','Paramedic']],m?.license||'',false)}${select('traineeId','Linked trainee profile',[['','Choose'],...app.people.map(p=>[p.id,p.name])],m?.traineeId||'',false)}<p>Role assignment does not appoint an FTO or grant site-sharing access. Admins cannot approve their own training.</p>${actions('Save account roles')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'member',member:{email:v.email,name:v.name,roles:['admin','trainer','trainee'].filter(r=>v[r]==='on'),license:v.license,traineeId:v.traineeId}});await load();closeModal()})}
function personForm(id){const p=app.people.find(p=>p.id===id);showModal(p?'Edit trainee':'Add trainee',`<form id="activeForm">${field('name','Trainee name','text',p?.name||'')}${select('license','License',['EMT','AEMT','Paramedic'],p?.license||'EMT')}${field('startDate','Hire / training start','date',p?.startDate||'')}<label class="field">Assigned FTO<select disabled><option>Unassigned — complete pre-ride clearance first</option></select></label><p>After clearance, use the approved-FTO dropdown in Onboarding. There is no automatic hour-based release.</p>${actions('Save trainee')}</form>`);bindForm(async v=>{await request('/config','POST',{etag:app.configEtag,action:'person',person:{...v,id,pathway:p?.pathway||'Standard'}});await load();closeModal()})}
function reuFormList(s){return [{type:'shift',label:'FTO trainee evaluation',record:s},{type:'response',label:'Response / driving log',record:s.traineeResponse},{type:'feedback',label:'Evaluation of trainer',record:s.trainerFeedback},{type:'pqs',label:'Daily PQS',record:s.dailyPqs}]}
function shiftsView(){if(!person())return empty('Select a trainee.');const d=data();return heading('REU shift forms','Shift paperwork','All submissions require Admin approval. Overdue means more than 12 hours after shift end.',selectPerson())+(!mine()&&!d.release?`<div class="actions">${button('Create completed shift record','openShift()','primary')}${button('Flag training concern','concernForm()')}</div>`:'')+live(d.shifts).slice().reverse().map(s=>card(date(s.start)+' · Day / phase '+s.phase,`<p>${esc(datetime(s.start))} – ${esc(datetime(s.end))}</p>${mine()?`<div class="actions">${button('My daily checklist',`openDailyPqs(${arg(s.id)})`)}${button('My response / driving log',`responseForm(${arg(s.id)},'response')`)}${button('My evaluation of trainer',`responseForm(${arg(s.id)},'feedback')`)}</div>`:`<div class="actions">${button('Daily PQS',`openDailyPqs(${arg(s.id)})`)}${s.status==='Draft'?(s.evaluator===me().email?button('Edit my evaluation',`openShift(${arg(s.id)})`)+button('Sign and submit',`submitShift(${arg(s.id)})`):badge('Awaiting original FTO correction')):button('View evaluation',`viewShift(${arg(s.id)})`)}${button('Response / driving log',`viewResponseLog(${arg(s.id)})`)}${s.status!=='Draft'?button('Request correction',`correctionForm(${arg(s.id)},'shift')`):''}</div>`}${reuFormList(s).filter(f=>!mine()||f.type!=='shift').map(f=>`<p class="small">${esc(f.label)}: ${esc(f.record?.status||'Not submitted')}${Date.now()>Date.parse(s.end)+12*3600000&&!['Submitted','Signed','Reviewed'].includes(f.record?.status)?' · <strong>Overdue</strong>':''}${mine()&&['Submitted','Reviewed'].includes(f.record?.status)?` ${button('Request correction',`correctionForm(${arg(s.id)},${arg(f.type)})`)}`:''}</p>`).join('')}`)).join('')}
function openShift(id){const s=data().shifts.find(s=>s.id===id),old=s?.reuEvaluation,keys=['onTime','dressed','binder','prepared','expectations'],labels=['Arrived on time','Appropriately dressed','Presented training binder','Prepared for shift','Explained shift expectations'];showModal('REU trainee shift evaluation',`<form id="activeForm"><div class="formgrid">${field('start','Shift start','datetime-local',localInput(s?.start||new Date(Date.now()-8*3600000)))}${field('end','Shift end','datetime-local',localInput(s?.end||new Date()))}${field('unit','Unit','text',old?.unit||'')}${select('level','Unit operating level',['ALS','LALS','BLS'],old?.level||'BLS')}</div>${keys.map((k,i)=>select(k,labels[i],[['','Choose'],['Yes','Yes'],['No','No']],old?.readiness[k]===true?'Yes':old?.readiness[k]===false?'No':'')).join('')}${Object.entries(app.workflow.domains).map(([k,label])=>`<h3>${esc(label)}</h3>${select('rating-'+k,'Rating',[['','Not observed'],...app.workflow.ratings.map((r,i)=>[i+1,r])],old?.ratings[k]??'',false)}${area('comment-'+k,'FTO comments',old?.comments[k]||'',false)}`).join('')}${area('objectives','Shift objectives',s?.objectives||'')}${area('overall','Overall FTO comments',old?.overall||'')}${check('criticalFailure','A safety concern occurred — automatically place training on hold',s?.criticalFailure)}${check('coaching','Coaching was needed',s?.coaching)}${actions('Save evaluation draft')}</form>`);bindForm(async v=>{await mutate('shift',{shift:{id,start:new Date(v.start).toISOString(),end:new Date(v.end).toISOString(),phase:s?.phase||data().currentPhase,objectives:v.objectives,sharedFeedback:v.overall,privateNotes:'',excludedMinutes:0,ratings:{},encounters:[],criticalFailure:v.criticalFailure==='on',coaching:v.coaching==='on',reuEvaluation:{unit:v.unit,level:v.level,readiness:Object.fromEntries(keys.map(k=>[k,v[k]==='Yes'])),ratings:Object.fromEntries(Object.keys(app.workflow.domains).map(k=>[k,v['rating-'+k]===''?null:Number(v['rating-'+k])])),comments:Object.fromEntries(Object.keys(app.workflow.domains).map(k=>[k,v['comment-'+k]])),overall:v.overall}}});closeModal()})}
function viewShift(id){const s=data().shifts.find(s=>s.id===id);if(mine())return;showModal('FTO evaluation · '+date(s.start),s.reuEvaluation?`<p>${esc(s.evaluatorName)} · ${esc(s.status)}</p>${Object.entries(app.workflow.domains).map(([k,label])=>`<h3>${esc(label)} — ${esc(s.reuEvaluation.ratings[k]?app.workflow.ratings[s.reuEvaluation.ratings[k]-1]:'Not observed')}</h3><p>${esc(s.reuEvaluation.comments[k]||'')}</p>`).join('')}<h3>Overall</h3><p>${esc(s.reuEvaluation.overall)}</p>`:`<h3>Historical FTO evaluation</h3>${readableObject({evaluator:s.evaluatorName||s.evaluator,status:s.status,objectives:s.objectives,ratings:s.ratings,coaching:s.sharedFeedback,evaluatorComments:s.privateNotes,attestation:s.attestation})}`)}
function responseForm(id,kind){const s=data().shifts.find(s=>s.id===id),old=kind==='response'?s.traineeResponse:s.trainerFeedback;if(old&&!['Draft','Returned'].includes(old.status)){showModal('My submitted form',`<p>Status: ${esc(old.status)}</p>${readableObject(old)}${button('Request correction',`correctionForm(${arg(id)},${arg(kind==='response'?'response':'feedback')})`)}`);return}showModal(kind==='response'?'Response / driving log':'Evaluate my trainer',`<form id="activeForm"><input type="hidden" name="draft" value="false">${kind==='response'?`<p>Add each call once. This is also your driving log. Use run numbers only; no patient identifiers.</p>${check('noCalls','No calls on this shift',old?.noCalls)}<div id="reuRuns"></div><button type="button" onclick="addReuRun()">Add response</button>`:app.workflow.feedbackKeys.map((k,i)=>select(k,app.workflow.feedback[i],['Yes','No','Not observed'],old?.answers?.[k]||'Not observed')).join('')+area('topics','Topics for further training',old?.topics||'',false)+area('skills','Skills performed',old?.skills||'',false)+area('comments','Comments regarding your trainer',old?.comments||'',false)+area('improvements','Suggested improvements',old?.improvements||'',false)}${check('attest','I confirm this accurately records my own submission.')}<p id="formError" class="form-error"></p><div class="actions"><button type="submit" formnovalidate onclick="this.form.elements.draft.value='true'">Save draft</button><button class="primary" onclick="this.form.elements.draft.value='false'">Sign and submit</button></div></form>`);if(kind==='response')for(const r of old?.runs||[])addReuRun(r);bindForm(async(v,form)=>{const runs=[...form.querySelectorAll('.reu-run')].map(el=>Object.fromEntries([...el.querySelectorAll('input,select')].map(x=>[x.dataset.key,x.value])));await mutate(kind,{shiftId:id,draft:v.draft==='true',attest:v.attest==='on',form:kind==='response'?{runs,noCalls:v.noCalls==='on'}:{answers:Object.fromEntries(app.workflow.feedbackKeys.map(k=>[k,v[k]])),topics:v.topics,skills:v.skills,comments:v.comments,improvements:v.improvements}});closeModal()})}
function addReuRun(v={}){const fields=[['date','Date','date',v.date||''],['reference','Run number','text',v.reference||''],['priority','Response priority','text',v.priority||''],['preceptor','FTO / preceptor','text',v.preceptor||data().assignment?.ftoName||'']];$('#reuRuns').insertAdjacentHTML('beforeend',`<section class="reu-run pqs-item"><div class="formgrid">${fields.map(([k,l,t,value])=>`<label>${l}<input data-key="${k}" type="${t}" value="${esc(value)}"></label>`).join('')}<label>Role<select data-key="role">${['Drive','Observe','Assist','Lead'].map(x=>`<option ${v.role===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Level of care<select data-key="level">${['ALS','LALS','BLS'].map(x=>`<option ${v.level===x?'selected':''}>${x}</option>`).join('')}</select></label></div><button type="button" onclick="this.closest('.reu-run').remove()">Remove row</button></section>`)}
function viewResponseLog(id){const s=data().shifts.find(s=>s.id===id);showModal('Response / driving log',`${readableObject(s.traineeResponse||{status:'Not submitted'})}`)}
function correctionForm(id,type){showModal('Ask an Admin to return this form',`<form id="activeForm">${area('notes','What needs correction?')}${actions('Request return')}</form>`);bindForm(async v=>{await mutate('request-correction',{shiftId:id,type,notes:v.notes});closeModal()})}
function concernsView(){return heading('Restricted to Admins and assigned FTOs','Training concerns','Open concerns stop training and advancement until Admin review.',selectPerson())+button('Flag concern','concernForm()','primary')+(data().concerns||[]).map(c=>card(esc(c.title),`<p>Status: ${esc(c.status)}</p><p>${esc(c.details)}</p><p>Action taken: ${esc(c.actionTaken||'')}</p><p>Reported by ${esc(c.name||c.by)} · ${esc(datetime(c.at))}</p>${admin()?button('Review concern',`concernReview(${arg(c.id)})`):''}${c.review?`<p>Admin review: ${esc(c.review.notes)}</p>`:''}`)).join('')}
function concernForm(){showModal('Flag a training concern',`<form id="activeForm"><p>This immediately places training and advancement on hold until Admin review.</p>${field('title','Concern title')}${area('details','Observed issue — no patient identifiers')}${area('actionTaken','Action already taken')}${area('requested','Requested follow-up','',false)}${actions('Flag and hold training')}</form>`);bindForm(async v=>{await mutate('flag-concern',v);closeModal()})}
function concernReview(id){showModal('Review training concern',`<form id="activeForm">${select('decision','Decision',['Cleared','Remediation required','Duties restricted'])}${area('notes','Decision, restrictions, remediation and follow-up')}<p>Only Cleared lifts this concern’s hold. Other open concerns still block training.</p>${actions('Record review')}</form>`);bindForm(async v=>{await mutate('review-concern',{...v,concernId:id});closeModal()})}
function reviewView(){let html=heading('Shared Admin review queue','Forms, corrections and overdue paperwork','Routine pending approvals do not stop training. Concerns do.');for(const p of app.people){const d=app.enrollments[p.id].data;for(const s of live(d.shifts))for(const f of reuFormList(s)){const requests=(d.corrections||[]).filter(x=>x.shiftId===s.id&&x.type===f.type&&x.status==='Open'),due=Date.now()>Date.parse(s.end)+12*3600000&&!['Submitted','Signed','Reviewed'].includes(f.record?.status);if(['Submitted','Signed'].includes(f.record?.status)||requests.length||due)html+=card(esc(p.name)+' · '+esc(f.label),`<p>${esc(date(s.start))} · ${esc(f.record?.status||'Not submitted')}${due?' · Overdue':''}</p>${requests.map(r=>`<p>Correction requested by ${esc(r.by)}: ${esc(r.reason)}</p>`).join('')}${f.record?button('Read submitted form',`readAdminForm(${arg(p.id)},${arg(s.id)},${arg(f.type)})`):''}${['Submitted','Signed','Reviewed'].includes(f.record?.status)?button('Approve / return',`reviewReuForm(${arg(p.id)},${arg(s.id)},${arg(f.type)})`):''}`)}}return html}
function readAdminForm(pid,sid,type){if(!admin())return;const s=app.enrollments[pid].data.shifts.find(x=>x.id===sid),f=reuFormList(s).find(x=>x.type===type);showModal(f.label,`<div class="reading">${readableObject(f.record)}</div>`)}
function readableObject(value){if(value==null)return 'Not recorded';if(Array.isArray(value))return value.map((v,i)=>`<section class="pqs-item"><h3>Entry ${i+1}</h3>${readableObject(v)}</section>`).join('');if(typeof value==='object')return Object.entries(value).filter(([k])=>!['history','snapshot','audit','id','actorId'].includes(k)).map(([k,v])=>`<div class="readable-field"><strong>${esc(({hrOrientation:'TargetSolutions orientation',hrRelease:'HR release',fit:'Fit test',im:'IM training',cevo:'CEVO driving course',map:'Map and area knowledge test',process:'FTO process explanation',reuEvaluation:'FTO evaluation',by:'Recorded by',at:'Date and time',ftoEmail:'Assigned FTO email',ftoName:'Assigned FTO',firstShift:'Next scheduled shift',pqsRequired:'Daily checklist required',traineeResponse:'Response and driving log',trainerFeedback:'Trainee evaluation of trainer',dailyPqs:'Daily checklist',shown:'Shown or explained',practiced:'Practiced or operated',outcome:'FTO observed result',evaluatorSignature:'Evaluator signature',traineeSignature:'Trainee signature'})[k]||labelFor(k))}</strong><div>${k==='ratings'&&v&&typeof v==='object'?Object.entries(v).map(([name,score])=>`<p>${esc(app.workflow.domains[name]||labelFor(name))}: ${score==null?'Not observed':esc(app.workflow.ratings[score-1]||score)}</p>`).join(''):readableObject(v)}</div></div>`).join('');return esc(typeof value==='boolean'?(value?'Yes':'No'):value)}
function reviewReuForm(pid,sid,type){selected=pid;showModal('Approve or return paperwork',`<form id="activeForm">${select('decision','Decision',['Approve','Return'])}${area('notes','Review notes or required corrections')}${actions('Record review')}</form>`);bindForm(async v=>{await mutate('review-paperwork',{...v,shiftId:sid,type});closeModal()})}
function trainingHub(){if(!person())return empty('No trainee assigned.');const d=data(),phase=app.catalog.phases.find(x=>x.id===d.currentPhase);return heading('REU training','Day / phase '+d.currentPhase+' · '+phase.title,reuStatus(),selectPerson())+card('What to do this training day',`<ul>${(phase.reuFocus||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Unfinished tasks remain in this phase until successfully demonstrated. FTO advancement requires every applicable task to be complete.</p>${button('My daily checklists',"go('Daily PQS')",'primary')}`)+(!mine()?card('FTO progression',`<p>${rec().phaseBlockers.map(esc).join('<br>')}</p>${button('Advance / recommend final test-out',`decision('fto-advance','Confirm demonstrated competence','Document completed tasks and Acceptable or higher observed performance. Final-phase completion recommends test-out; only an Admin releases independent duty.')`)}`):'')}
function pathView(){return trainingHub()}
function phaseReviewForm(){decision('fto-advance','FTO advancement','All tasks, evaluations and paperwork must meet the REU standard.')}
function reuReport(result,full=false){const d=result.record,p=result.person;return printable((full?'Full training record':'Compact training summary')+' — '+p.name,`<h2>Who this record is about</h2><p>${esc(p.name)} · License: ${esc(p.license)}<br>Started: ${esc(p.startDate)}<br>Assigned trainer: ${esc(d.assignment?.ftoName||'Not assigned')}<br>Current status: ${esc(result.readiness.status)}</p><h2>Before the first ride</h2>${Object.entries(app.workflow.onboarding).map(([k,label])=>`<p><strong>${esc(label)}:</strong> ${d.onboarding?.items[k]?'Completed · '+esc(d.onboarding.items[k].by)+' · '+esc(datetime(d.onboarding.items[k].at)):'Not verified'}</p>`).join('')}<p>First-ride clearance: ${d.onboarding?.clearance?esc(d.onboarding.clearance.name)+' · '+esc(datetime(d.onboarding.clearance.at)):'Not approved'}</p><h2>Training progress</h2>${app.catalog.phases.map(ph=>`<p><strong>Phase ${ph.id}: ${esc(ph.title)}</strong><br>${d.phaseReviews.filter(x=>x.phase===ph.id&&x.decision==='Advance').map(x=>'Completed · '+esc(x.by)+' · '+esc(datetime(x.at))).join('')||'Not completed'}</p>`).join('')}<h2>Paperwork status</h2><table><tr><th>Shift</th><th>Form</th><th>Status</th><th>Approved by</th></tr>${live(d.shifts).flatMap(s=>reuFormList(s).map(f=>`<tr><td>${esc(date(s.start))}</td><td>${esc(f.label)}</td><td>${esc(f.record?.status||'Not submitted')}</td><td>${esc(f.record?.review?.by||'Not approved')}</td></tr>`)).join('')}</table><h2>Final testing</h2><p>Written assessment: Not yet developed.<br>Practical skills assessment: Not yet developed.<br>Final approval: ${result.release?esc(result.release.name)+' · '+esc(result.release.effectiveDate):'Not released for independent duty'}</p>${full?`<h2>Original forms and supporting records</h2>${live(d.shifts).map(s=>`<h3>Shift ${esc(date(s.start))}</h3>${reuFormList(s).map(f=>`<h4>${esc(f.label)}</h4>${readableObject(f.record)}`).join('')}`).join('')}<h2>Concerns, corrections and decisions</h2>${readableObject({concerns:d.concerns||[],corrections:d.corrections||[],phaseReviews:d.phaseReviews})}<h2>Corrections and earlier signed versions</h2>${live(d.shifts).map(s=>`<h3>Shift ${esc(date(s.start))}</h3>${(s.history||[]).map(h=>`<details><summary>Earlier version — ${esc(datetime(h.at))}</summary>${readableObject(h.data)}</details>`).join('')}${(s.dailyPqs?.history||[]).map(h=>`<details><summary>Earlier checklist — ${esc(datetime(h.at))}</summary><p>Returned by ${esc(h.by)}: ${esc(h.reason)}</p>${readableObject(h.snapshot)}</details>`).join('')}`).join('')}<h2>Record activity</h2>${(d.audit||[]).map(e=>`<p>${esc(datetime(e.at))} · ${esc(e.actor)} · ${esc(e.action.replaceAll('-',' '))}</p>`).join('')}`:''}`)}
async function downloadReuReport(full){if(!admin())return;try{const result=await request('/trainees/'+encodeURIComponent(selected)+'/report');download(reuReport(result,full),'REU-'+result.person.name.replace(/[^a-z0-9]/gi,'-')+(full?'-full-record.html':'-compact-summary.html'))}catch(e){toast(e.message)}}
function downloadReport(){return downloadReuReport(true)}
function downloadCompactReport(){return downloadReuReport(false)}
function examView(){if(!admin())return empty('Combined records and final test-out administration are Admin-only.');return heading('Admin-only record','Training record and final test-out','Plain-language progress, completed forms and final-release status.',selectPerson())+card('Downloads',button('Download compact summary','downloadCompactReport()','primary')+button('Download full record','downloadReport()'))+card('Current status',`<p>${esc(reuStatus())}</p><p>${rdy().blockers.map(esc).join('<br>')}</p>`)+card('Assessments awaiting development','<p>Map and response-area test: Not yet developed.</p><p>Final written test: Not yet developed.</p><p>Final practical assessment: Not yet developed.</p><p>Historical test results remain in the full record. They do not substitute for the new REU written and practical test-out. Final release stays unavailable until both assessments are developed and passed, with the Training Officer and a second reviewer recorded.</p>')+card('Read the training record',readableObject({onboarding:data().onboarding,assignment:data().assignment,phaseDecisions:data().phaseReviews,concerns:data().concerns,release:data().release}))}
function activityDescription(e){const names={'session-open':'Signed in / opened the website','signout-intent':'Selected sign out','page-view':'Opened a website page','form-open':'Opened a form','onboarding-item':'Verified a pre-ride requirement','clear-first-ride':'Cleared a hire for their first ride','assign-fto':'Assigned or changed an FTO','review-paperwork':'Reviewed training paperwork','flag-concern':'Flagged a concern and placed training on hold','review-concern':'Reviewed a training concern','request-correction':'Asked an Admin to return a form','fto-advance':'Advanced a trainee or recommended final test-out','daily-pqs-save':'Saved a daily checklist draft','daily-pqs-submit':'Submitted a daily checklist','daily-pqs-sign':'Signed a trainee’s checklist','shift':'Saved an FTO evaluation draft','submit-shift':'Signed and submitted an FTO evaluation','response':'Saved or submitted a response / driving log','feedback':'Saved or submitted an evaluation of a trainer'};if(names[e.action])return names[e.action];if(e.path.endsWith('/report'))return 'Opened or downloaded a combined training record';if(e.path.includes('/bootstrap'))return 'Loaded a role workspace';if(e.status===401)return 'Tried to access the website without signing in';if(e.status===403)return 'Tried to access a page or action without permission';return labelFor(e.action.replaceAll('-',' ').replaceAll('/api/academy',''))}
function activityView(){if(!admin())return empty('Admin access required.');if(!activityData&&!activityLoading)queueMicrotask(()=>loadActivity(false));return heading('Admin-only website record','Website activity','Who used the website, what they did, and whether it worked.',button('Refresh','loadActivity(false)'))+card('Find activity',`<form onsubmit="event.preventDefault();applyActivityFilters()" id="activityFilter">${field('q','Search person, action or record','search',activityFilters.q,false)}${field('from','From date (UTC)','date',activityFilters.from,false)}${field('to','Through date (UTC)','date',activityFilters.to,false)}<input type="hidden" name="category" value="">${check('includeDemo','Include role-test activity',activityFilters.includeDemo)}<button class="primary">Search</button></form>`)+card('Activity history',activityData?.events?.map(e=>`<section class="pqs-item"><strong>${esc(e.actor_email)} — ${esc(activityDescription(e))}</strong><p>${esc(datetime(e.at))} · ${esc(reuRoleName(e.role))} · ${e.phase==='Attempt'?'Attempt started':e.status>=400?'Did not succeed':'Completed successfully'}${e.demonstration?' · Sample workspace':''}</p><details><summary>Technical details</summary><p>${esc(e.method)} ${esc(e.path)}<br>Request ${esc(e.request_id)} · Result ${esc(e.status||'Pending')}</p>${readableObject(e.details)}</details></section>`).join('')||empty('No matching activity loaded.'))+(activityData?.next?button('Load earlier activity','loadActivity(true)'):'')}

async function openOnboardingPdf(kind){if(!admin())return;const tab=window.open('about:blank','_blank');try{const response=await fetch('/api/academy/onboarding/forms/'+kind,{credentials:'same-origin',headers:{...presentationHeaders(),...(sessionStorage.getItem('reu-active-role')?{'X-REU-Role':sessionStorage.getItem('reu-active-role')}:{})}});if(!response.ok){const v=await response.json();throw Error(v.error||'Form unavailable.')}const url=URL.createObjectURL(await response.blob());if(tab)tab.location=url;else{const a=document.createElement('a');a.href=url;a.download=({im:'REU_IM_Fillable.pdf',cevo:'REU_CEVO_Fillable.pdf',map:'REU_Map_Test_Layout_Draft.pdf','map-key':'REU_Map_Test_Admin_Key_Draft.pdf'})[kind];a.click()}setTimeout(()=>URL.revokeObjectURL(url),300000)}catch(e){if(tab)tab.close();toast(e.message)}}
function onboardingView(){return legacy_onboardingView()+(!admin()?'':card('Completed onboarding paperwork — Admin only',`<p class="small">Open a blank form, fill it in and save the completed PDF to your device. Use Verify actual completion to attach that saved copy to this trainee. Changes in a browser PDF tab do not automatically save to the training record.</p>${(data().attachments||[]).filter(f=>f.scope==='admin-onboarding').map(f=>row(f.formKind.toUpperCase()+' · '+f.name,'Saved '+datetime(f.at)+' by '+f.by,button('Open completed copy',`downloadEvidence(${arg(f.id)},${arg(f.name)})`))).join('')||empty('No completed onboarding PDFs have been attached.')}<p class="small">The original checklist wording is retained. Follow current approved REU protocols and equipment instructions. CEVO forms retain the original program-use notice.</p>`))}
function onboardingForm(item){if(!['im','cevo'].includes(item))return legacy_onboardingForm(item);const files=(data().attachments||[]).filter(f=>f.scope==='admin-onboarding'&&f.formKind===item&&f.mime==='application/pdf');showModal(app.workflow.onboarding[item]+' — completion evidence',`<form id="activeForm"><p>Open the blank form, complete and save it, then attach the completed PDF below.</p><button type="button" onclick="openOnboardingPdf(${arg(item)})">Open fillable ${item.toUpperCase()} PDF</button>${field('completedDate','Actual completion date','date','')}${field('evaluatorName','Evaluator name','text',me().name)}${field('reference','Completion evidence / certificate reference')}${select('fileId','Use a previously attached completed PDF',[['','Upload a new completed PDF below'],...files.map(f=>[f.id,f.name])],'',false)}<label class="field">Completed PDF<input type="file" name="completedPdf" accept="application/pdf"></label><p class="small">Verification records your signed-in Admin identity and time. Completed documents are restricted to Admins.</p>${actions('Attach and verify completion')}</form>`);bindForm(async(v,form)=>{let fileId=v.fileId;const file=form.elements.completedPdf.files[0];if(file){const response=await fetch('/api/academy/trainees/'+encodeURIComponent(selected)+'/upload',{method:'POST',credentials:'same-origin',headers:{...presentationHeaders(),...(sessionStorage.getItem('reu-active-role')?{'X-REU-Role':sessionStorage.getItem('reu-active-role')}:{ }),'Content-Type':'application/pdf','X-Onboarding-Form':item,'X-File-Name':encodeURIComponent(file.name),'X-Record-Version':rec().etag||'new'},body:file});const result=await response.json();if(!response.ok)throw Error(result.error||'Upload failed.');fileId=result.fileId;await load()}if(!fileId)throw Error('Attach the completed PDF before verifying this requirement.');await mutate('onboarding-item',{item,completed:true,completedDate:v.completedDate,evaluatorName:v.evaluatorName,reference:v.reference,fileId});closeModal();toast('Completed PDF attached and training verified')})}

const reuThemes={dark:['Midnight Dark','#1f3855','#346caa','#101722'],reu:['REU Classic','#14263c','#a42e46','#f4f6f9'],ocean:['Ocean Blue','#163e59','#176899','#eef6fb'],forest:['Forest Green','#183e32','#24694e','#f0f6ef'],lavender:['Lavender','#393056','#70509a','#f5f1fa'],warm:['Warm Sand','#47382d','#87552d','#faf5eb'],contrast:['High Contrast','#101820','#172b4d','#ffffff']};
function themeStorageKey(){return 'reu-personal-theme:'+String(me()?.email||me()?.id||me()?.name||'employee')}
function currentTheme(){try{const v=localStorage.getItem(themeStorageKey());return reuThemes[v]?v:'reu'}catch{return 'reu'}}
function applyPersonalTheme(value){const t=reuThemes[value]||reuThemes.reu;for(const [key,color]of [['--navy',t[1]],['--red',t[2]],['--bg',t[3]]])document.documentElement.style.setProperty(key,color);document.documentElement.dataset.theme=value}
function themeSelector(){const value=currentTheme();applyPersonalTheme(value);return `<label class="personal-theme">Theme <select aria-label="Personal website theme" onchange="setPersonalTheme(this.value)">${Object.entries(reuThemes).map(([key,t])=>`<option value="${key}" ${key===value?'selected':''}>${t[0]}</option>`).join('')}</select></label>`}
function setPersonalTheme(value){if(!reuThemes[value])return;applyPersonalTheme(value);try{localStorage.setItem(themeStorageKey(),value);toast('Theme saved on this device')}catch{toast('Theme applied for this visit')}}
